  1	<script>
  2	const API_BASE = "http://localhost:8000";
  3	
  4	// In-memory only — deliberately not persisted to localStorage.
  5	let session = { token: null, role: null, sportScope: null };
  6	let drafts = []; // [{id, version}]
  7	
  8	function authHeaders() {
  9	  return session.token ? { "Authorization": "Bearer " + session.token } : {};
 10	}
 11	
 12	async function api(path, options = {}) {
 13	  const res = await fetch(API_BASE + path, {
 14	    ...options,
 15	    headers: { "Content-Type": "application/json", ...authHeaders(), ...(options.headers || {}) },
 16	  });
 17	  const body = await res.json().catch(() => ({}));
 18	  return { ok: res.ok, status: res.status, body };
 19	}
 20	
 21	function showMsg(elId, text, ok) {
 22	  document.getElementById(elId).innerHTML =
 23	    `<div class="msg ${ok ? "good" : "bad"}">${text}</div>`;
 24	}
 25	
 26	// ---------- Auth ----------
 27	async function login() {
 28	  const email = document.getElementById("login-email").value;
 29	  const password = [REDACTED]"login-password").value;
 30	  const { ok, body } = await api("/auth/login", { method: "POST", body: JSON.stringify({ email, password }) });
 31	  if (!ok) { showMsg("login-msg", body.detail || "Login failed", false); return; }
 32	
 33	  session = { token: body.access_token, role: body.role, sportScope: body.sport_scope };
 34	  document.getElementById("login-box").style.display = "none";
 35	  document.getElementById("organizer-box").style.display = "block";
 36	  document.getElementById("logout-btn").style.display = "inline";
 37	  document.getElementById("session-text").innerHTML =
 38	    `<b>${session.role}</b>${session.sportScope ? " &middot; " + session.sportScope : " &middot; global scope"}`;
 39	}
 40	
 41	function logout() {
 42	  session = { token: null, role: null, sportScope: null };
 43	  drafts = [];
 44	  renderDrafts();
 45	  document.getElementById("login-box").style.display = "block";
 46	  document.getElementById("organizer-box").style.display = "none";
 47	  document.getElementById("logout-btn").style.display = "none";
 48	  document.getElementById("session-text").textContent = "Not signed in";
 49	}
 50	document.getElementById("logout-btn").onclick = logout;
 51	
 52	// ---------- Tabs ----------
 53	document.querySelectorAll(".tab").forEach(tab => {
 54	  tab.onclick = () => {
 55	    document.querySelectorAll(".tab").forEach(t => t.classList.remove("active"));
 56	    document.querySelectorAll(".tab-panel").forEach(p => p.classList.remove("active"));
 57	    tab.classList.add("active");
 58	    document.getElementById("tab-" + tab.dataset.tab).classList.add("active");
 59	  };
 60	});
 61	
 62	// ---------- Public schedule (no auth) ----------
 63	async function loadPublicSchedule() {
 64	  const { ok, body } = await api("/schedules?season=active");
 65	  const tbody = document.getElementById("public-schedule-body");
 66	  if (!ok || !body.length) {
 67	    tbody.innerHTML = `<tr class="empty-row"><td colspan="5">No confirmed matches yet.</td></tr>`;
 68	    return;
 69	  }
 70	  tbody.innerHTML = body.map(m => `
 71	    <tr>
 72	      <td>${m.id}</td>
 73	      <td>${m.sport}</td>
 74	      <td>Team ${m.home_team_id} vs Team ${m.away_team_id}</td>
 75	      <td>Venue ${m.venue_id}</td>
 76	      <td>${m.start_time}</td>
 77	    </tr>`).join("");
 78	}
 79	loadPublicSchedule();
 80	setInterval(loadPublicSchedule, 5000);
 81	
 82	// ---------- Book a match ----------
 83	async function bookMatch() {
 84	  const payload = {
 85	    home_team_id: Number(document.getElementById("b-home").value),
 86	    away_team_id: Number(document.getElementById("b-away").value),
 87	    venue_id: Number(document.getElementById("b-venue").value),
 88	    sport: document.getElementById("b-sport").value,
 89	    start_time: document.getElementById("b-start").value,
 90	    end_time: document.getElementById("b-end").value,
 91	    season_id: Number(document.getElementById("b-season").value),
 92	  };
 93	  const { ok, status, body } = await api("/schedules", { method: "POST", body: JSON.stringify(payload) });
 94	  if (!ok) {
 95	    const detail = typeof body.detail === "object" ? JSON.stringify(body.detail.conflicts) : body.detail;
 96	    showMsg("book-msg", `${status}: ${detail}`, false);
 97	    return;
 98	  }
 99	  showMsg("book-msg", `Draft created: match #${body.match_id} (version ${body.version})`, true);
100	  drafts.push({ id: body.match_id, version: body.version });
101	  renderDrafts();
102	}
103	
104	// ---------- Roster ----------
105	async function addPlayer() {
106	  const payload = {
107	    name: document.getElementById("p-name").value,
108	    roll_number: document.getElementById("p-roll").value,
109	    team_id: Number(document.getElementById("p-team").value),
110	    sport: document.getElementById("p-sport").value,
111	    season_id: Number(document.getElementById("p-season").value),
112	  };
113	  const { ok, status, body } = await api("/players", { method: "POST", body: JSON.stringify(payload) });
114	  showMsg("roster-msg", ok ? `Added: player #${body.player_id} → team #${body.team_id}` : `${status}: ${body.detail}`, ok);
115	}
116	
117	// ---------- Async generation ----------
118	async function generateSchedule() {
119	  let fixtures;
120	  try { fixtures = JSON.parse(document.getElementById("g-fixtures").value); }
121	  catch (e) { showMsg("generate-msg", "Invalid JSON in fixtures", false); return; }
122	
123	  const payload = {
124	    sport: document.getElementById("g-sport").value,
125	    season_id: Number(document.getElementById("g-season").value),
126	    fixtures,
127	  };
128	  const { ok, status, body } = await api("/schedule-generations", { method: "POST", body: JSON.stringify(payload) });
129	  if (!ok) { showMsg("generate-msg", `${status}: ${body.detail}`, false); return; }
130	
131	  showMsg("generate-msg", `Job #${body.job_id} queued — polling…`, true);
132	  pollJob(body.job_id);
133	}
134	
135	async function pollJob(jobId) {
136	  const { body } = await api(`/schedule-generations/${jobId}`);
137	  showMsg("generate-msg",
138	    `<span class="status-pill ${body.status}">${body.status}</span> job #${jobId}`, true);
139	
140	  if (body.status === "QUEUED" || body.status === "RUNNING") {
141	    setTimeout(() => pollJob(jobId), 700);
142	    return;
143	  }
144	  if (body.status === "COMPLETED") {
145	    const created = body.result.created_draft_match_ids || [];
146	    created.forEach(id => drafts.push({ id, version: 1 }));
147	    renderDrafts();
148	    showMsg("generate-msg",
149	      `Done — ${created.length} draft(s) created, ${body.result.skipped.length} skipped (conflicts). See Drafts tab.`, true);
150	  } else {
151	    showMsg("generate-msg", `Job failed: ${JSON.stringify(body.result)}`, false);
152	  }
153	}
154	
155	// ---------- Drafts / publish ----------
156	function renderDrafts() {
157	  const tbody = document.getElementById("drafts-body");
158	  if (!drafts.length) {
159	    tbody.innerHTML = `<tr class="empty-row"><td colspan="3">No drafts yet — book a match or generate a schedule.</td></tr>`;
160	    return;
161	  }
162	  tbody.innerHTML = drafts.map((d, i) => `
163	    <tr>
164	      <td>#${d.id}</td>
165	      <td>v${d.version}</td>
166	      <td><button class="secondary" onclick="publishDraft(${i})">Publish</button></td>
167	    </tr>`).join("");
168	}
169	
170	async function publishDraft(index) {
171	  const d = drafts[index];
172	  const { ok, status, body } = await api(`/schedules/${d.id}/publish`, {
173	    method: "POST", body: JSON.stringify({ expected_version: d.version }),
174	  });
175	  if (!ok) {
176	    const detail = typeof body.detail === "object" ? JSON.stringify(body.detail.conflicts) : body.detail;
177	    showMsg("publish-msg", `#${d.id} → ${status}: ${detail}`, false);
178	    return;
179	  }
180	  showMsg("publish-msg", `#${d.id} published (now v${body.version})`, true);
181	  drafts.splice(index, 1);
182	  renderDrafts();
183	  loadPublicSchedule();
184	}
185	
186	renderDrafts();
187	</script>
188	</body>
189	</html>

