/* ============================================================================
   Intramural Scheduler — Onyx + Candy Blue
   Hand-written CSS. No framework, no reset library, no build step.

   The palette is deliberately almost monochrome. Candy Blue is spent on
   exactly one thing per view — the action you are most likely to want — so
   that it actually reads as special (Von Restorff). Everything that is merely
   available is onyx and grey.
   ========================================================================= */

:root {
  /* Onyx ramp — surfaces, darkest to lightest */
  --onyx-900: #0b0d10;
  --onyx-800: #101317;
  --onyx-700: #161a20;
  --onyx-600: #1c212a;
  --onyx-500: #232936;
  --line:     #2b3240;
  --line-soft:#212734;

  /* Candy Blue — the single accent */
  --candy-400: #63c9ff;
  --candy-500: #2bb3ff;
  --candy-600: #0d98e8;
  --candy-700: #0a7ab9;
  --candy-glow: rgba(43, 179, 255, 0.32);
  --candy-wash: rgba(43, 179, 255, 0.10);

  /* Text */
  --text:      #e9edf4;
  --text-dim:  #9aa6b8;
  --text-faint:#6b7687;
  --on-candy:  #04202f;

  /* Semantic — each conflict kind gets its own hue so they are told apart
     at a glance rather than by reading the label. */
  --ok:        #3ddc97;
  --ok-wash:   rgba(61, 220, 151, 0.12);
  --venue:     #ff6b6b;   /* venue clash */
  --venue-wash:rgba(255, 107, 107, 0.12);
  --player:    #ffb454;   /* double-booked player */
  --player-wash:rgba(255, 180, 84, 0.12);
  --blackout:  #b79cff;   /* not a clash — not enough rest */
  --blackout-wash: rgba(183, 156, 255, 0.13);

  --radius:   10px;
  --radius-sm: 7px;
  --radius-lg: 14px;

  /* Fitts's Law: nothing interactive is smaller than this. */
  --tap: 44px;

  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto,
          Helvetica, Arial, sans-serif;
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;

  /* One spring, used everywhere, so every press feels like the same product */
  --spring: cubic-bezier(0.34, 1.56, 0.64, 1);
  --ease:   cubic-bezier(0.4, 0, 0.2, 1);
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  background: var(--onyx-900);
  color: var(--text);
  font-family: var(--sans);
  font-size: 15px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, p { margin: 0; }

button, input, select, textarea { font: inherit; color: inherit; }

:focus-visible {
  outline: 2px solid var(--candy-500);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ---------------------------------------------------------------- app bar */

.appbar {
  position: sticky;
  top: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 0 20px;
  height: 60px;
  background: rgba(16, 19, 23, 0.86);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--line);
}

.brand { display: flex; align-items: center; gap: 11px; min-width: 0; }

.brand-mark {
  width: 30px; height: 30px;
  border-radius: 9px;
  display: grid; place-items: center;
  background: linear-gradient(145deg, var(--candy-400), var(--candy-600));
  color: var(--on-candy);
  font-weight: 800;
  font-size: 14px;
  letter-spacing: -0.5px;
  box-shadow: 0 3px 14px var(--candy-glow);
  flex: none;
}

.brand-name {
  font-size: 15px; font-weight: 650; letter-spacing: -0.2px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}

.appbar-right { display: flex; align-items: center; gap: 10px; }

/* Term badge — ambient context, never competes with the accent */
.term-badge {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 5px 11px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--onyx-700);
  font-size: 12.5px;
  color: var(--text-dim);
  white-space: nowrap;
}
.term-badge b { color: var(--text); font-weight: 600; }
.term-badge .dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--ok);
  box-shadow: 0 0 0 3px var(--ok-wash);
}
.term-badge.is-break .dot { background: var(--player); box-shadow: 0 0 0 3px var(--player-wash); }

.session-chip {
  display: flex; align-items: center; gap: 9px;
  padding: 5px 6px 5px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--onyx-700);
  font-size: 12.5px;
}
.session-chip .who { color: var(--text); font-weight: 600; }
.session-chip .scope { color: var(--text-faint); }

/* ------------------------------------------------------------------ layout */

.shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 400px;
  gap: 20px;
  padding: 20px;
  max-width: 1500px;
  margin: 0 auto;
  align-items: start;
}

@media (max-width: 1040px) {
  .shell { grid-template-columns: 1fr; }
  .rail { order: -1; }           /* on narrow screens, act first, browse after */
}

.panel {
  background: var(--onyx-800);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.panel-head {
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px;
  padding: 15px 18px;
  border-bottom: 1px solid var(--line-soft);
}

.panel-title { font-size: 14px; font-weight: 650; letter-spacing: -0.15px; }

.panel-sub { font-size: 12.5px; color: var(--text-faint); margin-top: 2px; }

.panel-body { padding: 18px; }

/* Proximity: a group of related controls sits tight together, and groups are
   separated by roughly double that gap. Nothing else signals the grouping. */
.group { display: flex; flex-direction: column; gap: 14px; }
.group + .group { margin-top: 26px; padding-top: 22px; border-top: 1px solid var(--line-soft); }
.group-label {
  font-size: 11px; font-weight: 700; letter-spacing: 0.9px;
  text-transform: uppercase; color: var(--text-faint);
  margin-bottom: -4px;
}

.field { display: flex; flex-direction: column; gap: 6px; }  /* label hugs input */
.row2 { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }

label {
  font-size: 12.5px;
  color: var(--text-dim);
  font-weight: 550;
}

input, select {
  width: 100%;
  min-height: var(--tap);
  padding: 10px 12px;
  background: var(--onyx-600);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  color: var(--text);
  transition: border-color 140ms var(--ease), box-shadow 140ms var(--ease),
              background-color 140ms var(--ease);
}
input::placeholder { color: var(--text-faint); }
input:hover, select:hover { border-color: #38404f; }
input:focus, select:focus {
  outline: none;
  border-color: var(--candy-500);
  background: var(--onyx-500);
  box-shadow: 0 0 0 3px var(--candy-wash);
}
select { cursor: pointer; appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--text-dim) 50%),
                    linear-gradient(135deg, var(--text-dim) 50%, transparent 50%);
  background-position: calc(100% - 17px) 50%, calc(100% - 12px) 50%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  padding-right: 34px;
}

.hint { font-size: 11.5px; color: var(--text-faint); }

/* ----------------------------------------------------- buttons: press+spring
   Press compresses fast and linearly (it should feel immediate), release
   overshoots on a spring (it should feel alive). Same curve everywhere.      */

.btn {
  position: relative;
  display: inline-flex; align-items: center; justify-content: center;
  gap: 8px;
  min-height: var(--tap);
  padding: 11px 18px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: var(--onyx-500);
  color: var(--text);
  font-size: 14px; font-weight: 600;
  cursor: pointer;
  user-select: none;
  will-change: transform;
  transition: transform 300ms var(--spring),
              background-color 150ms var(--ease),
              border-color 150ms var(--ease),
              box-shadow 200ms var(--ease),
              opacity 150ms var(--ease);
}
.btn:hover { background: #2a3140; }
.btn:active { transform: scale(0.955); transition: transform 80ms ease-out; }
.btn:disabled { opacity: 0.45; cursor: not-allowed; transform: none; }

/* Von Restorff: exactly one of these per panel. */
.btn-primary {
  width: 100%;
  background: linear-gradient(175deg, var(--candy-400), var(--candy-500) 55%, var(--candy-600));
  color: var(--on-candy);
  font-weight: 700;
  box-shadow: 0 2px 10px var(--candy-glow), inset 0 1px 0 rgba(255,255,255,0.28);
}
.btn-primary:hover {
  background: linear-gradient(175deg, #79d2ff, var(--candy-500) 55%, var(--candy-600));
  box-shadow: 0 4px 18px var(--candy-glow), inset 0 1px 0 rgba(255,255,255,0.32);
}
.btn-primary:active { transform: scale(0.965); }

.btn-ghost {
  background: transparent;
  border-color: var(--line);
  color: var(--text-dim);
  min-height: 38px;
  padding: 7px 13px;
  font-size: 13px;
}
.btn-ghost:hover { background: var(--onyx-600); color: var(--text); border-color: #38404f; }

.btn-danger-ghost { composes: btn-ghost; }
.btn-ghost.danger:hover { color: var(--venue); border-color: rgba(255,107,107,0.4); }

.btn-sm { min-height: 36px; padding: 6px 12px; font-size: 12.5px; }

/* Success pop — fires once when an action lands, then removes itself. */
@keyframes pop {
  0%   { transform: scale(0.955); }
  45%  { transform: scale(1.035); }
  100% { transform: scale(1); }
}
.btn.did-succeed { animation: pop 420ms var(--spring); }

/* Busy spinner, drawn in CSS */
.btn.is-busy { color: transparent !important; pointer-events: none; }
.btn.is-busy::after {
  content: "";
  position: absolute; inset: 0; margin: auto;
  width: 17px; height: 17px;
  border: 2px solid rgba(255,255,255,0.28);
  border-top-color: currentColor;
  border-radius: 50%;
  color: var(--on-candy);
  animation: spin 620ms linear infinite;
}
.btn-ghost.is-busy::after { color: var(--text); }
@keyframes spin { to { transform: rotate(360deg); } }

/* --------------------------------------------------------------------- tabs
   Hick's Law: the organizer has five jobs, and only one set of controls is on
   screen at a time. The rest are one tap away, not competing for attention.  */

.tabs {
  display: flex;
  gap: 2px;
  padding: 5px;
  margin: 0;
  background: var(--onyx-700);
  border-bottom: 1px solid var(--line-soft);
  position: relative;
  overflow-x: auto;
  scrollbar-width: none;
}
.tabs::-webkit-scrollbar { display: none; }

.tab {
  flex: 1 0 auto;
  min-height: 40px;
  padding: 8px 14px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-dim);
  font-size: 13px; font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: color 160ms var(--ease), background-color 160ms var(--ease),
              transform 300ms var(--spring);
}
.tab:hover { color: var(--text); background: var(--onyx-600); }
.tab:active { transform: scale(0.94); transition: transform 80ms ease-out; }
.tab[aria-selected="true"] {
  background: var(--onyx-500);
  color: var(--text);
  box-shadow: inset 0 0 0 1px var(--line);
}
.tab[aria-selected="true"]::after {
  content: "";
  position: absolute;
  bottom: 3px;
  height: 2px; width: 22px;
  border-radius: 2px;
  background: var(--candy-500);
  transform: translateX(-50%);
  margin-left: 0;
  display: none;   /* the filled pill already reads as selected */
}

.tabpanel { display: none; }
.tabpanel.is-active { display: block; animation: panel-in 260ms var(--ease); }
@keyframes panel-in {
  from { opacity: 0; transform: translateY(5px); }
  to   { opacity: 1; transform: none; }
}

/* ------------------------------------------------------------- schedule list */

.sched-list { display: flex; flex-direction: column; }

.day-head {
  position: sticky; top: 60px;
  z-index: 5;
  padding: 9px 18px;
  background: var(--onyx-700);
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
  font-size: 11.5px; font-weight: 700;
  letter-spacing: 0.7px; text-transform: uppercase;
  color: var(--text-dim);
  display: flex; justify-content: space-between; align-items: center;
}
.day-head .count { color: var(--text-faint); font-weight: 600; letter-spacing: 0; text-transform: none; }

.match {
  display: grid;
  grid-template-columns: 74px minmax(0,1fr) auto;
  gap: 14px;
  align-items: center;
  padding: 13px 18px;
  border-bottom: 1px solid var(--line-soft);
  animation: row-in 300ms var(--ease) both;
}
.match:last-child { border-bottom: none; }
@keyframes row-in {
  from { opacity: 0; transform: translateY(-4px); }
  to   { opacity: 1; transform: none; }
}

.match-time {
  font-family: var(--mono);
  font-size: 13px; font-weight: 600;
  color: var(--text);
  letter-spacing: -0.3px;
}
.match-time .dur { display: block; font-size: 11px; color: var(--text-faint); font-weight: 400; }

.match-main { min-width: 0; }
.match-teams {
  font-size: 14px; font-weight: 600;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.match-meta {
  font-size: 12px; color: var(--text-faint);
  display: flex; gap: 8px; align-items: center; flex-wrap: wrap;
  margin-top: 2px;
}
.match-meta .sep { opacity: 0.4; }

.pill {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 11px; font-weight: 650;
  letter-spacing: 0.3px;
  border: 1px solid transparent;
}
.pill-sport { background: var(--onyx-500); color: var(--text-dim); border-color: var(--line); }
.pill-term  { background: var(--candy-wash); color: var(--candy-400); border-color: rgba(43,179,255,0.25); }
.pill-draft { background: var(--player-wash); color: var(--player); border-color: rgba(255,180,84,0.3); }
.pill-live  { background: var(--ok-wash); color: var(--ok); border-color: rgba(61,220,151,0.3); }

/* ------------------------------------------------------- conflicts (the point)
   Each kind is a different colour because they demand different responses:
   a venue clash means move the room, a player clash means pick someone else,
   a blackout means the player simply needs longer to recover.                */

.conflicts {
  margin-top: 14px;
  border: 1px solid rgba(255,107,107,0.35);
  border-radius: var(--radius);
  background: rgba(255,107,107,0.05);
  overflow: hidden;
  animation: shake 380ms var(--ease), panel-in 240ms var(--ease);
}
@keyframes shake {
  0%,100% { transform: translateX(0); }
  22% { transform: translateX(-5px); }
  44% { transform: translateX(4px); }
  66% { transform: translateX(-2px); }
}

.conflicts-head {
  padding: 10px 13px;
  font-size: 12.5px; font-weight: 700;
  color: var(--venue);
  border-bottom: 1px solid rgba(255,107,107,0.2);
  display: flex; align-items: center; gap: 8px;
}

.conflict {
  display: flex; gap: 10px;
  padding: 10px 13px;
  border-bottom: 1px solid var(--line-soft);
  font-size: 12.5px;
}
.conflict:last-child { border-bottom: none; }

.conflict-bar { width: 3px; border-radius: 2px; flex: none; }
.c-venue           .conflict-bar { background: var(--venue); }
.c-venue_external  .conflict-bar { background: var(--venue); }
.c-player          .conflict-bar { background: var(--player); }
.c-player_external .conflict-bar { background: var(--player); }
.c-blackout          .conflict-bar { background: var(--blackout); }
.c-blackout_external .conflict-bar { background: var(--blackout); }
.c-invalid .conflict-bar { background: var(--text-faint); }

.conflict-kind { font-weight: 700; margin-bottom: 1px; }
.c-venue .conflict-kind, .c-venue_external .conflict-kind { color: var(--venue); }
.c-player .conflict-kind, .c-player_external .conflict-kind { color: var(--player); }
.c-blackout .conflict-kind, .c-blackout_external .conflict-kind { color: var(--blackout); }
.c-invalid .conflict-kind { color: var(--text-dim); }
.conflict-why { color: var(--text-dim); }
.conflict-why b { color: var(--text); font-weight: 600; }

/* rest meter — shows how far short the recovery gap falls */
.rest-meter {
  margin-top: 6px;
  height: 5px;
  border-radius: 3px;
  background: var(--onyx-500);
  overflow: hidden;
}
.rest-meter span {
  display: block; height: 100%;
  background: var(--blackout);
  border-radius: 3px;
  transition: width 700ms var(--spring);
}

/* --------------------------------------------------------------- draft cards
   Fitts: the button that acts on a draft sits inside that draft's own card,
   so the pointer barely travels from reading it to acting on it.             */

.draft {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--onyx-700);
  padding: 13px;
  animation: row-in 280ms var(--ease) both;
}
.draft + .draft { margin-top: 10px; }
.draft-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; }
.draft-id { font-family: var(--mono); font-size: 12px; color: var(--text-faint); }
.draft-teams { font-size: 13.5px; font-weight: 600; margin-top: 3px; }
.draft-when { font-size: 12px; color: var(--text-dim); margin-top: 2px; }
.draft-actions { display: flex; gap: 8px; margin-top: 12px; }
.draft-actions .btn { flex: 1; }

.draft.is-leaving { animation: row-out 280ms var(--ease) forwards; }
@keyframes row-out {
  to { opacity: 0; transform: translateX(14px) scale(0.97); max-height: 0; margin: 0; padding-block: 0; }
}

/* ------------------------------------------------------------------- states */

.empty {
  padding: 42px 22px;
  text-align: center;
  color: var(--text-faint);
}
.empty-mark {
  width: 42px; height: 42px; margin: 0 auto 12px;
  border-radius: 12px;
  border: 1px dashed var(--line);
  display: grid; place-items: center;
  font-size: 18px;
  color: var(--text-faint);
}
.empty-title { color: var(--text-dim); font-weight: 600; font-size: 13.5px; }
.empty-body { font-size: 12.5px; margin-top: 3px; }

.skeleton {
  height: 56px;
  border-bottom: 1px solid var(--line-soft);
  background: linear-gradient(90deg, var(--onyx-700) 25%, var(--onyx-600) 37%, var(--onyx-700) 63%);
  background-size: 400% 100%;
  animation: shimmer 1.3s ease-in-out infinite;
}
@keyframes shimmer { from { background-position: 100% 0; } to { background-position: 0 0; } }

/* inline result line under a form */
.result {
  margin-top: 12px;
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  font-size: 12.5px;
  border: 1px solid transparent;
  animation: panel-in 220ms var(--ease);
}
.result.ok  { background: var(--ok-wash);  color: var(--ok);  border-color: rgba(61,220,151,0.28); }
.result.bad { background: var(--venue-wash); color: var(--venue); border-color: rgba(255,107,107,0.28); }
.result.info{ background: var(--onyx-600); color: var(--text-dim); border-color: var(--line); }

/* job progress */
.stage {
  display: flex; align-items: center; gap: 10px;
  padding: 11px 13px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--onyx-700);
  margin-top: 12px;
  font-size: 12.5px;
}
.stage-dot {
  width: 9px; height: 9px; border-radius: 50%;
  background: var(--text-faint);
  flex: none;
  transition: background-color 260ms var(--ease), box-shadow 260ms var(--ease);
}
.stage[data-state="QUEUED"]    .stage-dot { background: var(--text-dim); }
.stage[data-state="RUNNING"]   .stage-dot { background: var(--candy-500);
  box-shadow: 0 0 0 0 var(--candy-glow); animation: pulse 1.3s var(--ease) infinite; }
.stage[data-state="COMPLETED"] .stage-dot { background: var(--ok); box-shadow: 0 0 0 4px var(--ok-wash); }
.stage[data-state="FAILED"]    .stage-dot { background: var(--venue); box-shadow: 0 0 0 4px var(--venue-wash); }
@keyframes pulse {
  0%   { box-shadow: 0 0 0 0 var(--candy-glow); }
  70%  { box-shadow: 0 0 0 9px rgba(43,179,255,0); }
  100% { box-shadow: 0 0 0 0 rgba(43,179,255,0); }
}

/* --------------------------------------------------------------------- toast */

.toasts {
  position: fixed;
  right: 18px; bottom: 18px;
  z-index: 90;
  display: flex; flex-direction: column; gap: 9px;
  max-width: min(380px, calc(100vw - 36px));
}
.toast {
  display: flex; align-items: flex-start; gap: 10px;
  padding: 12px 14px;
  border-radius: var(--radius);
  background: var(--onyx-600);
  border: 1px solid var(--line);
  box-shadow: 0 10px 34px rgba(0,0,0,0.5);
  font-size: 13px;
  animation: toast-in 380ms var(--spring);
}
.toast.is-leaving { animation: toast-out 220ms var(--ease) forwards; }
@keyframes toast-in {
  from { opacity: 0; transform: translateY(14px) scale(0.94); }
  to   { opacity: 1; transform: none; }
}
@keyframes toast-out {
  to { opacity: 0; transform: translateX(22px) scale(0.97); }
}
.toast-bar { width: 3px; align-self: stretch; border-radius: 2px; background: var(--candy-500); flex: none; }
.toast.ok  .toast-bar { background: var(--ok); }
.toast.bad .toast-bar { background: var(--venue); }
.toast-title { font-weight: 650; }
.toast-body { color: var(--text-dim); font-size: 12.5px; margin-top: 1px; }

/* -------------------------------------------------------------------- misc */

.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

.stack { display: flex; flex-direction: column; gap: 10px; }
.between { display: flex; align-items: center; justify-content: space-between; gap: 10px; }

.kv { display: flex; justify-content: space-between; gap: 12px; font-size: 12.5px; padding: 6px 0; }
.kv + .kv { border-top: 1px solid var(--line-soft); }
.kv dt { color: var(--text-faint); }
.kv dd { margin: 0; color: var(--text); font-family: var(--mono); font-size: 12px; }

/* Honour the system setting. Motion here is decoration, never information. */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
  .btn:active { transform: none; }
}

toolUseResult.content:
/* ============================================================================
   Intramural Scheduler — Onyx + Candy Blue
   Hand-written CSS. No framework, no reset library, no build step.

   The palette is deliberately almost monochrome. Candy Blue is spent on
   exactly one thing per view — the action you are most likely to want — so
   that it actually reads as special (Von Restorff). Everything that is merely
   available is onyx and grey.
   ========================================================================= */

:root {
  /* Onyx ramp — surfaces, darkest to lightest */
  --onyx-900: #0b0d10;
  --onyx-800: #101317;
  --onyx-700: #161a20;
  --onyx-600: #1c212a;
  --onyx-500: #232936;
  --line:     #2b3240;
  --line-soft:#212734;

  /* Candy Blue — the single accent */
  --candy-400: #63c9ff;
  --candy-500: #2bb3ff;
  --candy-600: #0d98e8;
  --candy-700: #0a7ab9;
  --candy-glow: rgba(43, 179, 255, 0.32);
  --candy-wash: rgba(43, 179, 255, 0.10);

  /* Text */
  --text:      #e9edf4;
  --text-dim:  #9aa6b8;
  --text-faint:#6b7687;
  --on-candy:  #04202f;

  /* Semantic — each conflict kind gets its own hue so they are told apart
     at a glance rather than by reading the label. */
  --ok:        #3ddc97;
  --ok-wash:   rgba(61, 220, 151, 0.12);
  --venue:     #ff6b6b;   /* venue clash */
  --venue-wash:rgba(255, 107, 107, 0.12);
  --player:    #ffb454;   /* double-booked player */
  --player-wash:rgba(255, 180, 84, 0.12);
  --blackout:  #b79cff;   /* not a clash — not enough rest */
  --blackout-wash: rgba(183, 156, 255, 0.13);

  --radius:   10px;
  --radius-sm: 7px;
  --radius-lg: 14px;

  /* Fitts's Law: nothing interactive is smaller than this. */
  --tap: 44px;

  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto,
          Helvetica, Arial, sans-serif;
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;

  /* One spring, used everywhere, so every press feels like the same product */
  --spring: cubic-bezier(0.34, 1.56, 0.64, 1);
  --ease:   cubic-bezier(0.4, 0, 0.2, 1);
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  background: var(--onyx-900);
  color: var(--text);
  font-family: var(--sans);
  font-size: 15px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, p { margin: 0; }

button, input, select, textarea { font: inherit; color: inherit; }

:focus-visible {
  outline: 2px solid var(--candy-500);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ---------------------------------------------------------------- app bar */

.appbar {
  position: sticky;
  top: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 0 20px;
  height: 60px;
  background: rgba(16, 19, 23, 0.86);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--line);
}

.brand { display: flex; align-items: center; gap: 11px; min-width: 0; }

.brand-mark {
  width: 30px; height: 30px;
  border-radius: 9px;
  display: grid; place-items: center;
  background: linear-gradient(145deg, var(--candy-400), var(--candy-600));
  color: var(--on-candy);
  font-weight: 800;
  font-size: 14px;
  letter-spacing: -0.5px;
  box-shadow: 0 3px 14px var(--candy-glow);
  flex: none;
}

.brand-name {
  font-size: 15px; font-weight: 650; letter-spacing: -0.2px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}

.appbar-right { display: flex; align-items: center; gap: 10px; }

/* Term badge — ambient context, never competes with the accent */
.term-badge {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 5px 11px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--onyx-700);
  font-size: 12.5px;
  color: var(--text-dim);
  white-space: nowrap;
}
.term-badge b { color: var(--text); font-weight: 600; }
.term-badge .dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--ok);
  box-shadow: 0 0 0 3px var(--ok-wash);
}
.term-badge.is-break .dot { background: var(--player); box-shadow: 0 0 0 3px var(--player-wash); }

.session-chip {
  display: flex; align-items: center; gap: 9px;
  padding: 5px 6px 5px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--onyx-700);
  font-size: 12.5px;
}
.session-chip .who { color: var(--text); font-weight: 600; }
.session-chip .scope { color: var(--text-faint); }

/* ------------------------------------------------------------------ layout */

.shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 400px;
  gap: 20px;
  padding: 20px;
  max-width: 1500px;
  margin: 0 auto;
  align-items: start;
}

@media (max-width: 1040px) {
  .shell { grid-template-columns: 1fr; }
  .rail { order: -1; }           /* on narrow screens, act first, browse after */
}

.panel {
  background: var(--onyx-800);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.panel-head {
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px;
  padding: 15px 18px;
  border-bottom: 1px solid var(--line-soft);
}

.panel-title { font-size: 14px; font-weight: 650; letter-spacing: -0.15px; }

.panel-sub { font-size: 12.5px; color: var(--text-faint); margin-top: 2px; }

.panel-body { padding: 18px; }

/* Proximity: a group of related controls sits tight together, and groups are
   separated by roughly double that gap. Nothing else signals the grouping. */
.group { display: flex; flex-direction: column; gap: 14px; }
.group + .group { margin-top: 26px; padding-top: 22px; border-top: 1px solid var(--line-soft); }
.group-label {
  font-size: 11px; font-weight: 700; letter-spacing: 0.9px;
  text-transform: uppercase; color: var(--text-faint);
  margin-bottom: -4px;
}

.field { display: flex; flex-direction: column; gap: 6px; }  /* label hugs input */
.row2 { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }

label {
  font-size: 12.5px;
  color: var(--text-dim);
  font-weight: 550;
}

input, select {
  width: 100%;
  min-height: var(--tap);
  padding: 10px 12px;
  background: var(--onyx-600);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  color: var(--text);
  transition: border-color 140ms var(--ease), box-shadow 140ms var(--ease),
              background-color 140ms var(--ease);
}
input::placeholder { color: var(--text-faint); }
input:hover, select:hover { border-color: #38404f; }
input:focus, select:focus {
  outline: none;
  border-color: var(--candy-500);
  background: var(--onyx-500);
  box-shadow: 0 0 0 3px var(--candy-wash);
}
select { cursor: pointer; appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--text-dim) 50%),
                    linear-gradient(135deg, var(--text-dim) 50%, transparent 50%);
  background-position: calc(100% - 17px) 50%, calc(100% - 12px) 50%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  padding-right: 34px;
}

.hint { font-size: 11.5px; color: var(--text-faint); }

/* ----------------------------------------------------- buttons: press+spring
   Press compresses fast and linearly (it should feel immediate), release
   overshoots on a spring (it should feel alive). Same curve everywhere.      */

.btn {
  position: relative;
  display: inline-flex; align-items: center; justify-content: center;
  gap: 8px;
  min-height: var(--tap);
  padding: 11px 18px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: var(--onyx-500);
  color: var(--text);
  font-size: 14px; font-weight: 600;
  cursor: pointer;
  user-select: none;
  will-change: transform;
  transition: transform 300ms var(--spring),
              background-color 150ms var(--ease),
              border-color 150ms var(--ease),
              box-shadow 200ms var(--ease),
              opacity 150ms var(--ease);
}
.btn:hover { background: #2a3140; }
.btn:active { transform: scale(0.955); transition: transform 80ms ease-out; }
.btn:disabled { opacity: 0.45; cursor: not-allowed; transform: none; }

/* Von Restorff: exactly one of these per panel. */
.btn-primary {
  width: 100%;
  background: linear-gradient(175deg, var(--candy-400), var(--candy-500) 55%, var(--candy-600));
  color: var(--on-candy);
  font-weight: 700;
  box-shadow: 0 2px 10px var(--candy-glow), inset 0 1px 0 rgba(255,255,255,0.28);
}
.btn-primary:hover {
  background: linear-gradient(175deg, #79d2ff, var(--candy-500) 55%, var(--candy-600));
  box-shadow: 0 4px 18px var(--candy-glow), inset 0 1px 0 rgba(255,255,255,0.32);
}
.btn-primary:active { transform: scale(0.965); }

.btn-ghost {
  background: transparent;
  border-color: var(--line);
  color: var(--text-dim);
  min-height: 38px;
  padding: 7px 13px;
  font-size: 13px;
}
.btn-ghost:hover { background: var(--onyx-600); color: var(--text); border-color: #38404f; }

.btn-danger-ghost { composes: btn-ghost; }
.btn-ghost.danger:hover { color: var(--venue); border-color: rgba(255,107,107,0.4); }

.btn-sm { min-height: 36px; padding: 6px 12px; font-size: 12.5px; }

/* Success pop — fires once when an action lands, then removes itself. */
@keyframes pop {
  0%   { transform: scale(0.955); }
  45%  { transform: scale(1.035); }
  100% { transform: scale(1); }
}
.btn.did-succeed { animation: pop 420ms var(--spring); }

/* Busy spinner, drawn in CSS */
.btn.is-busy { color: transparent !important; pointer-events: none; }
.btn.is-busy::after {
  content: "";
  position: absolute; inset: 0; margin: auto;
  width: 17px; height: 17px;
  border: 2px solid rgba(255,255,255,0.28);
  border-top-color: currentColor;
  border-radius: 50%;
  color: var(--on-candy);
  animation: spin 620ms linear infinite;
}
.btn-ghost.is-busy::after { color: var(--text); }
@keyframes spin { to { transform: rotate(360deg); } }

/* --------------------------------------------------------------------- tabs
   Hick's Law: the organizer has five jobs, and only one set of controls is on
   screen at a time. The rest are one tap away, not competing for attention.  */

.tabs {
  display: flex;
  gap: 2px;
  padding: 5px;
  margin: 0;
  background: var(--onyx-700);
  border-bottom: 1px solid var(--line-soft);
  position: relative;
  overflow-x: auto;
  scrollbar-width: none;
}
.tabs::-webkit-scrollbar { display: none; }

.tab {
  flex: 1 0 auto;
  min-height: 40px;
  padding: 8px 14px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-dim);
  font-size: 13px; font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: color 160ms var(--ease), background-color 160ms var(--ease),
              transform 300ms var(--spring);
}
.tab:hover { color: var(--text); background: var(--onyx-600); }
.tab:active { transform: scale(0.94); transition: transform 80ms ease-out; }
.tab[aria-selected="true"] {
  background: var(--onyx-500);
  color: var(--text);
  box-shadow: inset 0 0 0 1px var(--line);
}
.tab[aria-selected="true"]::after {
  content: "";
  position: absolute;
  bottom: 3px;
  height: 2px; width: 22px;
  border-radius: 2px;
  background: var(--candy-500);
  transform: translateX(-50%);
  margin-left: 0;
  display: none;   /* the filled pill already reads as selected */
}

.tabpanel { display: none; }
.tabpanel.is-active { display: block; animation: panel-in 260ms var(--ease); }
@keyframes panel-in {
  from { opacity: 0; transform: translateY(5px); }
  to   { opacity: 1; transform: none; }
}

/* ------------------------------------------------------------- schedule list */

.sched-list { display: flex; flex-direction: column; }

.day-head {
  position: sticky; top: 60px;
  z-index: 5;
  padding: 9px 18px;
  background: var(--onyx-700);
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
  font-size: 11.5px; font-weight: 700;
  letter-spacing: 0.7px; text-transform: uppercase;
  color: var(--text-dim);
  display: flex; justify-content: space-between; align-items: center;
}
.day-head .count { color: var(--text-faint); font-weight: 600; letter-spacing: 0; text-transform: none; }

.match {
  display: grid;
  grid-template-columns: 74px minmax(0,1fr) auto;
  gap: 14px;
  align-items: center;
  padding: 13px 18px;
  border-bottom: 1px solid var(--line-soft);
  animation: row-in 300ms var(--ease) both;
}
.match:last-child { border-bottom: none; }
@keyframes row-in {
  from { opacity: 0; transform: translateY(-4px); }
  to   { opacity: 1; transform: none; }
}

.match-time {
  font-family: var(--mono);
  font-size: 13px; font-weight: 600;
  color: var(--text);
  letter-spacing: -0.3px;
}
.match-time .dur { display: block; font-size: 11px; color: var(--text-faint); font-weight: 400; }

.match-main { min-width: 0; }
.match-teams {
  font-size: 14px; font-weight: 600;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.match-meta {
  font-size: 12px; color: var(--text-faint);
  display: flex; gap: 8px; align-items: center; flex-wrap: wrap;
  margin-top: 2px;
}
.match-meta .sep { opacity: 0.4; }

.pill {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 11px; font-weight: 650;
  letter-spacing: 0.3px;
  border: 1px solid transparent;
}
.pill-sport { background: var(--onyx-500); color: var(--text-dim); border-color: var(--line); }
.pill-term  { background: var(--candy-wash); color: var(--candy-400); border-color: rgba(43,179,255,0.25); }
.pill-draft { background: var(--player-wash); color: var(--player); border-color: rgba(255,180,84,0.3); }
.pill-live  { background: var(--ok-wash); color: var(--ok); border-color: rgba(61,220,151,0.3); }

/* ------------------------------------------------------- conflicts (the point)
   Each kind is a different colour because they demand different responses:
   a venue clash means move the room, a player clash means pick someone else,
   a blackout means the player simply needs longer to recover.                */

.conflicts {
  margin-top: 14px;
  border: 1px solid rgba(255,107,107,0.35);
  border-radius: var(--radius);
  background: rgba(255,107,107,0.05);
  overflow: hidden;
  animation: shake 380ms var(--ease), panel-in 240ms var(--ease);
}
@keyframes shake {
  0%,100% { transform: translateX(0); }
  22% { transform: translateX(-5px); }
  44% { transform: translateX(4px); }
  66% { transform: translateX(-2px); }
}

.conflicts-head {
  padding: 10px 13px;
  font-size: 12.5px; font-weight: 700;
  color: var(--venue);
  border-bottom: 1px solid rgba(255,107,107,0.2);
  display: flex; align-items: center; gap: 8px;
}

.conflict {
  display: flex; gap: 10px;
  padding: 10px 13px;
  border-bottom: 1px solid var(--line-soft);
  font-size: 12.5px;
}
.conflict:last-child { border-bottom: none; }

.conflict-bar { width: 3px; border-radius: 2px; flex: none; }
.c-venue           .conflict-bar { background: var(--venue); }
.c-venue_external  .conflict-bar { background: var(--venue); }
.c-player          .conflict-bar { background: var(--player); }
.c-player_external .conflict-bar { background: var(--player); }
.c-blackout          .conflict-bar { background: var(--blackout); }
.c-blackout_external .conflict-bar { background: var(--blackout); }
.c-invalid .conflict-bar { background: var(--text-faint); }

.conflict-kind { font-weight: 700; margin-bottom: 1px; }
.c-venue .conflict-kind, .c-venue_external .conflict-kind { color: var(--venue); }
.c-player .conflict-kind, .c-player_external .conflict-kind { color: var(--player); }
.c-blackout .conflict-kind, .c-blackout_external .conflict-kind { color: var(--blackout); }
.c-invalid .conflict-kind { color: var(--text-dim); }
.conflict-why { color: var(--text-dim); }
.conflict-why b { color: var(--text); font-weight: 600; }

/* rest meter — shows how far short the recovery gap falls */
.rest-meter {
  margin-top: 6px;
  height: 5px;
  border-radius: 3px;
  background: var(--onyx-500);
  overflow: hidden;
}
.rest-meter span {
  display: block; height: 100%;
  background: var(--blackout);
  border-radius: 3px;
  transition: width 700ms var(--spring);
}

/* --------------------------------------------------------------- draft cards
   Fitts: the button that acts on a draft sits inside that draft's own card,
   so the pointer barely travels from reading it to acting on it.             */

.draft {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--onyx-700);
  padding: 13px;
  animation: row-in 280ms var(--ease) both;
}
.draft + .draft { margin-top: 10px; }
.draft-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; }
.draft-id { font-family: var(--mono); font-size: 12px; color: var(--text-faint); }
.draft-teams { font-size: 13.5px; font-weight: 600; margin-top: 3px; }
.draft-when { font-size: 12px; color: var(--text-dim); margin-top: 2px; }
.draft-actions { display: flex; gap: 8px; margin-top: 12px; }
.draft-actions .btn { flex: 1; }

.draft.is-leaving { animation: row-out 280ms var(--ease) forwards; }
@keyframes row-out {
  to { opacity: 0; transform: translateX(14px) scale(0.97); max-height: 0; margin: 0; padding-block: 0; }
}

/* ------------------------------------------------------------------- states */

.empty {
  padding: 42px 22px;
  text-align: center;
  color: var(--text-faint);
}
.empty-mark {
  width: 42px; height: 42px; margin: 0 auto 12px;
  border-radius: 12px;
  border: 1px dashed var(--line);
  display: grid; place-items: center;
  font-size: 18px;
  color: var(--text-faint);
}
.empty-title { color: var(--text-dim); font-weight: 600; font-size: 13.5px; }
.empty-body { font-size: 12.5px; margin-top: 3px; }

.skeleton {
  height: 56px;
  border-bottom: 1px solid var(--line-soft);
  background: linear-gradient(90deg, var(--onyx-700) 25%, var(--onyx-600) 37%, var(--onyx-700) 63%);
  background-size: 400% 100%;
  animation: shimmer 1.3s ease-in-out infinite;
}
@keyframes shimmer { from { background-position: 100% 0; } to { background-position: 0 0; } }

/* inline result line under a form */
.result {
  margin-top: 12px;
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  font-size: 12.5px;
  border: 1px solid transparent;
  animation: panel-in 220ms var(--ease);
}
.result.ok  { background: var(--ok-wash);  color: var(--ok);  border-color: rgba(61,220,151,0.28); }
.result.bad { background: var(--venue-wash); color: var(--venue); border-color: rgba(255,107,107,0.28); }
.result.info{ background: var(--onyx-600); color: var(--text-dim); border-color: var(--line); }

/* job progress */
.stage {
  display: flex; align-items: center; gap: 10px;
  padding: 11px 13px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--onyx-700);
  margin-top: 12px;
  font-size: 12.5px;
}
.stage-dot {
  width: 9px; height: 9px; border-radius: 50%;
  background: var(--text-faint);
  flex: none;
  transition: background-color 260ms var(--ease), box-shadow 260ms var(--ease);
}
.stage[data-state="QUEUED"]    .stage-dot { background: var(--text-dim); }
.stage[data-state="RUNNING"]   .stage-dot { background: var(--candy-500);
  box-shadow: 0 0 0 0 var(--candy-glow); animation: pulse 1.3s var(--ease) infinite; }
.stage[data-state="COMPLETED"] .stage-dot { background: var(--ok); box-shadow: 0 0 0 4px var(--ok-wash); }
.stage[data-state="FAILED"]    .stage-dot { background: var(--venue); box-shadow: 0 0 0 4px var(--venue-wash); }
@keyframes pulse {
  0%   { box-shadow: 0 0 0 0 var(--candy-glow); }
  70%  { box-shadow: 0 0 0 9px rgba(43,179,255,0); }
  100% { box-shadow: 0 0 0 0 rgba(43,179,255,0); }
}

/* --------------------------------------------------------------------- toast */

.toasts {
  position: fixed;
  right: 18px; bottom: 18px;
  z-index: 90;
  display: flex; flex-direction: column; gap: 9px;
  max-width: min(380px, calc(100vw - 36px));
}
.toast {
  display: flex; align-items: flex-start; gap: 10px;
  padding: 12px 14px;
  border-radius: var(--radius);
  background: var(--onyx-600);
  border: 1px solid var(--line);
  box-shadow: 0 10px 34px rgba(0,0,0,0.5);
  font-size: 13px;
  animation: toast-in 380ms var(--spring);
}
.toast.is-leaving { animation: toast-out 220ms var(--ease) forwards; }
@keyframes toast-in {
  from { opacity: 0; transform: translateY(14px) scale(0.94); }
  to   { opacity: 1; transform: none; }
}
@keyframes toast-out {
  to { opacity: 0; transform: translateX(22px) scale(0.97); }
}
.toast-bar { width: 3px; align-self: stretch; border-radius: 2px; background: var(--candy-500); flex: none; }
.toast.ok  .toast-bar { background: var(--ok); }
.toast.bad .toast-bar { background: var(--venue); }
.toast-title { font-weight: 650; }
.toast-body { color: var(--text-dim); font-size: 12.5px; margin-top: 1px; }

/* -------------------------------------------------------------------- misc */

.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

.stack { display: flex; flex-direction: column; gap: 10px; }
.between { display: flex; align-items: center; justify-content: space-between; gap: 10px; }

.kv { display: flex; justify-content: space-between; gap: 12px; font-size: 12.5px; padding: 6px 0; }
.kv + .kv { border-top: 1px solid var(--line-soft); }
.kv dt { color: var(--text-faint); }
.kv dd { margin: 0; color: var(--text); font-family: var(--mono); font-size: 12px; }

/* Honour the system setting. Motion here is decoration, never information. */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
  .btn:active { transform: none; }
}

input.content:
/**
 * Intramural Scheduler — frontend.
 *
 * TypeScript, no dependencies. Compiled to ../app.js by ../build.mjs, which
 * uses Node's own `module.stripTypeScriptTypes` — nothing is installed.
 *
 * Because types are *stripped* rather than transformed, this file avoids the
 * TypeScript constructs that need real codegen: no `enum`, no `namespace`, no
 * constructor parameter properties. Union types and `as const` cover the same
 * ground and survive stripping untouched.
 */

const API = (() => {
  // Served from a static server on another port during development, so the
  // API host is not simply `location.origin`.
  const override = new URLSearchParams(location.search).get("api");
  if (override) return override.replace(/\/$/, "");
  if (location.port === "8000") return location.origin;
  return "http://127.0.0.1:8000";
})();

/* ------------------------------------------------------------------- types */

type Role = "HEAD" | "REP" | "VIEWER";

interface Session {
  token: string;
  role: Role;
  sportScope: string | null;
  email: string;
}

interface Team { id: number; name: string; sport: string; season_id: number; }
interface Venue { id: number; name: string; location: string | null; }

interface Match {
  id: number;
  home_team_id: number;
  away_team_id: number;
  venue_id: number;
  start_time: string;
  end_time: string;
  status: string;
  sport: string;
  season_id: number;
  version: number;
}

interface Conflict {
  type: "venue" | "player" | "blackout" | "venue_external"
      | "player_external" | "blackout_external" | "invalid";
  player_name?: string;
  conflicting_match_id?: number;
  rest_minutes?: number;
  required_minutes?: number;
  description?: string;
  external_ref?: string;
  source?: string;
  reason?: string;
}

interface Draft {
  id: number;
  version: number;
  label: string;
  when: string;
  term: string;
}

interface ApiResult<T> { ok: boolean; status: number; body: T; }

/* --------------------------------------------------------------- app state */

const state: {
  session: Session | null;
  teams: Team[];
  venues: Venue[];
  drafts: Draft[];
  schedule: Match[];
  loadedOnce: boolean;
} = {
  session: null,
  teams: [],
  venues: [],
  drafts: [],
  schedule: [],
  loadedOnce: false,
};

/* ------------------------------------------------------------------ helpers */

function $<T extends HTMLElement>(id: string): T {
  const el = document.getElementById(id);
  if (!el) throw new Error(`missing element #${id}`);
  return el as T;
}

function el<K extends keyof HTMLElementTagNameMap>(
  tag: K, className?: string, text?: string
): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

function clear(node: HTMLElement): void {
  while (node.firstChild) node.removeChild(node.firstChild);
}

async function api<T = any>(
  path: string, options: RequestInit = {}
): Promise<ApiResult<T>> {
  const headers: Record<string, string> = { "Content-Type": "application/json" };
  if (state.session) headers["Authorization"] = `Bearer ${state.session.token}`;
  try {
    const res = await fetch(API + path, { ...options, headers: { ...headers, ...(options.headers as any) } });
    let body: any = null;
    try { body = await res.json(); } catch { body = null; }
    return { ok: res.ok, status: res.status, body: body as T };
  } catch (err) {
    return { ok: false, status: 0, body: { detail: "Cannot reach the API. Is the backend running?" } as any };
  }
}

/** Times arrive as canonical UTC; show them in the viewer's own zone. */
function fmtTime(iso: string): string {
  const d = new Date(iso);
  if (isNaN(d.getTime())) return iso;
  return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

function fmtDay(iso: string): string {
  const d = new Date(iso);
  if (isNaN(d.getTime())) return iso;
  return d.toLocaleDateString([], { weekday: "long", day: "numeric", month: "long", year: "numeric" });
}

function durationMins(a: string, b: string): number {
  return Math.round((new Date(b).getTime() - new Date(a).getTime()) / 60000);
}

function teamName(id: number): string {
  const t = state.teams.find(x => x.id === id);
  return t ? t.name : `Team ${id}`;
}

function venueName(id: number): string {
  const v = state.venues.find(x => x.id === id);
  return v ? v.name : `Venue ${id}`;
}

/* -------------------------------------------------------------------- toast */

function toast(title: string, body?: string, kind: "ok" | "bad" | "info" = "info"): void {
  const wrap = $("toasts");
  const node = el("div", `toast ${kind}`);
  node.appendChild(el("div", "toast-bar"));
  const textCol = el("div");
  textCol.appendChild(el("div", "toast-title", title));
  if (body) textCol.appendChild(el("div", "toast-body", body));
  node.appendChild(textCol);
  wrap.appendChild(node);
  setTimeout(() => {
    node.classList.add("is-leaving");
    setTimeout(() => node.remove(), 240);
  }, 4200);
}

/** Press feedback that outlives the click: a short spring pop on success. */
function pop(button: HTMLButtonElement): void {
  button.classList.remove("did-succeed");
  void button.offsetWidth;            // restart the animation
  button.classList.add("did-succeed");
  setTimeout(() => button.classList.remove("did-succeed"), 460);
}

async function withBusy<T>(button: HTMLButtonElement, work: () => Promise<T>): Promise<T> {
  button.classList.add("is-busy");
  button.disabled = true;
  try {
    return await work();
  } finally {
    button.classList.remove("is-busy");
    button.disabled = false;
  }
}

/* ---------------------------------------------------------------- conflicts */

/** Plain language, because the point is to tell the organizer what to DO. */
function describeConflict(c: Conflict): { kind: string; why: HTMLElement } {
  const why = el("div", "conflict-why");
  switch (c.type) {
    case "venue":
      why.innerHTML = `The venue is already booked by match <b>#${c.conflicting_match_id}</b> at that time. Move the room or the time.`;
      return { kind: "Venue double-booked", why };
    case "venue_external":
      why.innerHTML = `The master sheet already holds this venue — <b>${c.description || c.external_ref}</b>. Move the room or the time.`;
      return { kind: "Venue held in the master sheet", why };
    case "player":
      why.innerHTML = `<b>${c.player_name}</b> is already playing in match <b>#${c.conflicting_match_id}</b> then. They cannot be in two places.`;
      return { kind: "Player double-booked", why };
    case "player_external":
      why.innerHTML = `<b>${c.player_name}</b> is committed in the master sheet — <b>${c.description || c.external_ref}</b>.`;
      return { kind: "Player committed in the master sheet", why };
    case "blackout":
    case "blackout_external": {
      const rest = c.rest_minutes ?? 0;
      const need = c.required_minutes ?? 90;
      const where = c.type === "blackout_external"
        ? `the master sheet booking <b>${c.description || c.external_ref}</b>`
        : `match <b>#${c.conflicting_match_id}</b>`;
      why.innerHTML =
        `<b>${c.player_name}</b> would get only <b>${rest} min</b> of rest after ${where}. ` +
        `They need <b>${need} min</b>. Push this match ${need - rest} minutes later, or pick another player.`;
      const meter = el("div", "rest-meter");
      const fill = el("span");
      fill.style.width = "0%";
      meter.appendChild(fill);
      why.appendChild(meter);
      requestAnimationFrame(() => {
        fill.style.width = `${Math.min(100, Math.round((rest / need) * 100))}%`;
      });
      return { kind: "Not enough rest", why };
    }
    case "invalid":
      why.textContent = c.reason || "This match could not be checked.";
      return { kind: "Cannot be scheduled", why };
    default:
      why.textContent = JSON.stringify(c);
      return { kind: "Conflict", why };
  }
}

function renderConflicts(host: HTMLElement, conflicts: Conflict[]): void {
  const box = el("div", "conflicts");
  const head = el("div", "conflicts-head");
  head.textContent = conflicts.length === 1
    ? "1 reason this cannot be booked"
    : `${conflicts.length} reasons this cannot be booked`;
  box.appendChild(head);

  for (const c of conflicts) {
    const row = el("div", `conflict c-${c.type}`);
    row.appendChild(el("div", "conflict-bar"));
    const body = el("div");
    const { kind, why } = describeConflict(c);
    body.appendChild(el("div", "conflict-kind", kind));
    body.appendChild(why);
    row.appendChild(body);
    box.appendChild(row);
  }
  clear(host);
  host.appendChild(box);
}

function showResult(host: HTMLElement, text: string, kind: "ok" | "bad" | "info"): void {
  clear(host);
  host.appendChild(el("div", `result ${kind}`, text));
}

function errorText(body: any): string {
  if (!body) return "Something went wrong.";
  if (typeof body.detail === "string") return body.detail;
  if (Array.isArray(body.detail)) return body.detail.map((d: any) => d.msg || String(d)).join("; ");
  return JSON.stringify(body);
}

/* ------------------------------------------------------------ public schedule */

async function loadSchedule(): Promise<void> {
  const res = await api<Match[]>("/schedules?season=active");
  const host = $("schedule");

  if (!res.ok || !Array.isArray(res.body)) {
    if (!state.loadedOnce) {
      clear(host);
      host.appendChild(emptyState("!", "Cannot reach the scheduler",
        "Start the backend, then this list fills in on its own."));
    }
    return;
  }

  state.schedule = res.body;
  state.loadedOnce = true;
  $("match-count").textContent = res.body.length === 1 ? "1 match" : `${res.body.length} matches`;
  clear(host);

  if (res.body.length === 0) {
    host.appendChild(emptyState("—", "Nothing confirmed yet",
      "Published matches appear here for everyone, no sign-in needed."));
    return;
  }

  // Group by day — proximity again: same day, same block.
  const byDay = new Map<string, Match[]>();
  for (const m of res.body) {
    const key = fmtDay(m.start_time);
    const list = byDay.get(key);
    if (list) list.push(m); else byDay.set(key, [m]);
  }

  for (const [day, matches] of byDay) {
    const head = el("div", "day-head");
    head.appendChild(el("span", undefined, day));
    head.appendChild(el("span", "count", `${matches.length}`));
    host.appendChild(head);
    for (const m of matches) host.appendChild(matchRow(m));
  }
}

function matchRow(m: Match): HTMLElement {
  const row = el("div", "match");

  const time = el("div", "match-time");
  time.appendChild(document.createTextNode(fmtTime(m.start_time)));
  time.appendChild(el("span", "dur", `${durationMins(m.start_time, m.end_time)} min`));
  row.appendChild(time);

  const main = el("div", "match-main");
  main.appendChild(el("div", "match-teams", `${teamName(m.home_team_id)} vs ${teamName(m.away_team_id)}`));
  const meta = el("div", "match-meta");
  meta.appendChild(el("span", "pill pill-sport", m.sport));
  meta.appendChild(el("span", "sep", "·"));
  meta.appendChild(el("span", undefined, venueName(m.venue_id)));
  main.appendChild(meta);
  row.appendChild(main);

  row.appendChild(el("span", "pill pill-live", "Confirmed"));
  return row;
}

function emptyState(mark: string, title: string, body: string): HTMLElement {
  const wrap = el("div", "empty");
  wrap.appendChild(el("div", "empty-mark", mark));
  wrap.appendChild(el("div", "empty-title", title));
  wrap.appendChild(el("div", "empty-body", body));
  return wrap;
}

/* ----------------------------------------------------------- reference data */

async function loadReference(): Promise<void> {
  const [teams, venues] = await Promise.all([
    api<Team[]>("/teams"),
    api<Venue[]>("/venues"),
  ]);
  if (teams.ok && Array.isArray(teams.body)) state.teams = teams.body;
  if (venues.ok && Array.isArray(venues.body)) state.venues = venues.body;
  fillSelects();
}

/** Hick's Law: pick from the real, short list rather than typing an id. */
function fillSelects(): void {
  const sports = Array.from(new Set(state.teams.map(t => t.sport))).sort();
  const scope = state.session?.role === "REP" ? state.session.sportScope : null;
  const allowed = scope ? sports.filter(s => s === scope) : sports;

  const sportSel = $("b-sport") as HTMLSelectElement;
  const current = sportSel.value;
  clear(sportSel);
  for (const s of allowed) sportSel.appendChild(new Option(s, s));
  if (allowed.includes(current)) sportSel.value = current;

  const venueSel = $("b-venue") as HTMLSelectElement;
  clear(venueSel);
  for (const v of state.venues) venueSel.appendChild(new Option(v.name, String(v.id)));

  syncTeamOptions();

  const rosterTeam = $("p-team") as HTMLSelectElement;
  clear(rosterTeam);
  for (const t of state.teams) {
    if (!scope || t.sport === scope) {
      rosterTeam.appendChild(new Option(`${t.name} — ${t.sport}`, String(t.id)));
    }
  }
}

/** Only teams of the chosen sport can meet, so never offer the others. */
function syncTeamOptions(): void {
  const sport = ($("b-sport") as HTMLSelectElement).value;
  const eligible = state.teams.filter(t => t.sport === sport);
  for (const id of ["b-home", "b-away"]) {
    const sel = $(id) as HTMLSelectElement;
    const keep = sel.value;
    clear(sel);
    for (const t of eligible) sel.appendChild(new Option(t.name, String(t.id)));
    if (eligible.some(t => String(t.id) === keep)) sel.value = keep;
  }
  const home = $("b-home") as HTMLSelectElement;
  const away = $("b-away") as HTMLSelectElement;
  if (home.value === away.value && away.options.length > 1) away.selectedIndex = 1;
}

/* -------------------------------------------------------------------- auth */

async function signIn(button: HTMLButtonElement): Promise<void> {
  const email = ($("login-email") as HTMLInputElement).value.trim();
  const password = ($("login-password") as HTMLInputElement).value;
  const out = $("login-result");

  if (!email || !password) {
    showResult(out, "Enter your email and password.", "bad");
    return;
  }

  const res = await withBusy(button, () =>
    api<{ access_token: [REDACTED]; role: Role; sport_scope: string | null }>(
      "/auth/login", { method: "POST", body: JSON.stringify({ email, password }) }));

  if (!res.ok) {
    showResult(out, errorText(res.body), "bad");
    return;
  }

  state.session = {
    token: res.body.access_token,
    role: res.body.role,
    sportScope: res.body.sport_scope,
    email,
  };
  pop(button);
  clear(out);
  ($("login-password") as HTMLInputElement).value = "";
  renderSession();
  fillSelects();
  toast("Signed in", `${res.body.role}${res.body.sport_scope ? " · " + res.body.sport_scope : " · all sports"}`, "ok");
}

function signOut(): void {
  state.session = null;
  state.drafts = [];
  renderDrafts();
  renderSession();
  toast("Signed out", undefined, "info");
}

function renderSession(): void {
  const s = state.session;
  $("login-card").hidden = !!s;
  $("organizer").hidden = !s;
  $("session-chip").hidden = !s;
  $("admin-tab").hidden = !(s && s.role === "HEAD");

  if (s) {
    $("session-who").textContent = s.role;
    $("session-scope").textContent = s.sportScope ? s.sportScope : "all sports";
    if (!$("admin-tab").hidden === false && currentTab() === "admin") selectTab("book");
  }
}

/* ------------------------------------------------------------------ booking */

async function book(button: HTMLButtonElement): Promise<void> {
  const out = $("book-result");
  const home = Number(($("b-home") as HTMLSelectElement).value);
  const away = Number(($("b-away") as HTMLSelectElement).value);

  if (!home || !away) { showResult(out, "Pick both teams first.", "bad"); return; }
  if (home === away) { showResult(out, "A team cannot play itself.", "bad"); return; }

  const payload = {
    home_team_id: home,
    away_team_id: away,
    venue_id: Number(($("b-venue") as HTMLSelectElement).value),
    sport: ($("b-sport") as HTMLSelectElement).value,
    start_time: ($("b-start") as HTMLInputElement).value,
    end_time: ($("b-end") as HTMLInputElement).value,
  };

  const res = await withBusy(button, () =>
    api<any>("/schedules", { method: "POST", body: JSON.stringify(payload) }));

  if (res.status === 409 && res.body?.detail?.conflicts) {
    renderConflicts(out, res.body.detail.conflicts as Conflict[]);
    toast("Not booked", "The slot clashes — see the reasons.", "bad");
    return;
  }
  if (!res.ok) { showResult(out, errorText(res.body), "bad"); return; }

  pop(button);
  clear(out);
  state.drafts.unshift({
    id: res.body.match_id,
    version: res.body.version,
    label: `${teamName(home)} vs ${teamName(away)}`,
    when: `${fmtDay(payload.start_time)}, ${fmtTime(payload.start_time)}`,
    term: res.body.term,
  });
  renderDrafts();
  updateTermBadge(res.body.term, res.body.in_break);
  toast("Draft created", `Filed under ${res.body.term}. Publish it from Drafts.`, "ok");
  selectTab("drafts");
}

function updateTermBadge(term: string, inBreak: boolean): void {
  const badge = $("term-badge");
  badge.hidden = false;
  badge.classList.toggle("is-break", !!inBreak);
  $("term-label").textContent = term;
  $("term-note").textContent = inBreak ? "between trimesters" : "in session";
}

/* ------------------------------------------------------------------- drafts */

function renderDrafts(): void {
  const host = $("drafts");
  $("draft-count").textContent = String(state.drafts.length);
  clear(host);

  if (state.drafts.length === 0) {
    host.appendChild(emptyState("—", "No drafts yet",
      "Book a match or run a generation, and it lands here awaiting publish."));
    return;
  }

  for (const d of state.drafts) {
    const card = el("div", "draft");
    const top = el("div", "draft-top");
    const left = el("div");
    left.appendChild(el("div", "draft-teams", d.label));
    left.appendChild(el("div", "draft-when", d.when));
    top.appendChild(left);
    const right = el("div", "stack");
    right.appendChild(el("span", "draft-id", `#${d.id} · v${d.version}`));
    if (d.term) right.appendChild(el("span", "pill pill-term", d.term));
    top.appendChild(right);
    card.appendChild(top);

    const actions = el("div", "draft-actions");

    const publish = el("button", "btn btn-primary btn-sm", "Publish") as HTMLButtonElement;
    publish.addEventListener("click", () => publishDraft(d, publish, card));

    const cancel = el("button", "btn btn-ghost btn-sm danger", "Cancel") as HTMLButtonElement;
    cancel.addEventListener("click", () => cancelDraft(d, cancel, card));

    actions.appendChild(publish);
    actions.appendChild(cancel);
    card.appendChild(actions);

    const slot = el("div");
    card.appendChild(slot);
    host.appendChild(card);
  }
}

function removeDraft(d: Draft, card: HTMLElement): void {
  card.classList.add("is-leaving");
  setTimeout(() => {
    state.drafts = state.drafts.filter(x => x.id !== d.id);
    renderDrafts();
  }, 260);
}

async function publishDraft(d: Draft, button: HTMLButtonElement, card: HTMLElement): Promise<void> {
  const res = await withBusy(button, () =>
    api<any>(`/schedules/${d.id}/publish`, {
      method: "POST", body: JSON.stringify({ expected_version: d.version }),
    }));

  if (res.status === 409 && res.body?.detail?.conflicts) {
    const slot = card.lastElementChild as HTMLElement;
    renderConflicts(slot, res.body.detail.conflicts as Conflict[]);
    toast("Not published", "Something changed since the draft was made.", "bad");
    return;
  }
  if (!res.ok) { toast("Not published", errorText(res.body), "bad"); return; }

  pop(button);
  toast("Published", `Match #${d.id} is now public.`, "ok");
  removeDraft(d, card);
  loadSchedule();
}

async function cancelDraft(d: Draft, button: HTMLButtonElement, card: HTMLElement): Promise<void> {
  const res = await withBusy(button, () =>
    api<any>(`/schedules/${d.id}/cancel`, {
      method: "POST", body: JSON.stringify({ expected_version: d.version }),
    }));
  if (!res.ok) { toast("Not cancelled", errorText(res.body), "bad"); return; }
  toast("Cancelled", `Match #${d.id} released its venue and players.`, "ok");
  removeDraft(d, card);
  loadSchedule();
}

/* ------------------------------------------------------------------- roster */

async function addPlayer(button: HTMLButtonElement): Promise<void> {
  const out = $("roster-result");
  const payload = {
    name: ($("p-name") as HTMLInputElement).value.trim(),
    roll_number: ($("p-roll") as HTMLInputElement).value.trim(),
    team_id: Number(($("p-team") as HTMLSelectElement).value),
  };
  if (!payload.name || !payload.roll_number) {
    showResult(out, "Name and roll number are both needed.", "bad");
    return;
  }

  const res = await withBusy(button, () =>
    api<any>("/players", { method: "POST", body: JSON.stringify(payload) }));

  if (!res.ok) { showResult(out, errorText(res.body), "bad"); return; }
  pop(button);
  showResult(out, `Added ${payload.name} to ${teamName(payload.team_id)}.`, "ok");
  ($("p-name") as HTMLInputElement).value = "";
  ($("p-roll") as HTMLInputElement).value = "";
  toast("Roster updated", `${payload.name} joined ${teamName(payload.team_id)}.`, "ok");
}

/* --------------------------------------------------------------- generation */

async function generate(button: HTMLButtonElement): Promise<void> {
  const out = $("generate-result");
  let fixtures: any;
  try {
    fixtures = JSON.parse(($("g-fixtures") as HTMLTextAreaElement).value);
  } catch {
    showResult(out, "That is not valid JSON.", "bad");
    return;
  }

  const res = await withBusy(button, () =>
    api<any>("/schedule-generations", {
      method: "POST",
      body: JSON.stringify({ sport: ($("b-sport") as HTMLSelectElement).value, fixtures }),
    }));

  if (!res.ok) { showResult(out, errorText(res.body), "bad"); return; }
  pop(button);
  pollJob(res.body.job_id, out);
}

async function pollJob(jobId: number, out: HTMLElement): Promise<void> {
  clear(out);
  const stage = el("div", "stage");
  const dot = el("span", "stage-dot");
  const label = el("span", undefined, "Queued…");
  stage.appendChild(dot);
  stage.appendChild(label);
  out.appendChild(stage);

  for (let i = 0; i < 40; i++) {
    const res = await api<any>(`/schedule-generations/${jobId}`);
    const status = res.body?.status as string | undefined;
    if (!status) { showResult(out, errorText(res.body), "bad"); return; }

    stage.setAttribute("data-state", status);
    label.textContent =
      status === "QUEUED" ? "Queued…" :
      status === "RUNNING" ? "Solving fixtures…" :
      status === "COMPLETED" ? "Done" : "Failed";

    if (status === "COMPLETED") {
      const created: number[] = res.body.result?.created_draft_match_ids ?? [];
      const skipped: any[] = res.body.result?.skipped ?? [];
      label.textContent = `${created.length} draft${created.length === 1 ? "" : "s"} created, ${skipped.length} skipped`;

      for (const id of created) {
        state.drafts.unshift({ id, version: 1, label: `Generated match #${id}`, when: "from generation", term: "" });
      }
      renderDrafts();

      if (skipped.length) {
        const all: Conflict[] = [];
        for (const s of skipped) for (const c of s.conflicts) all.push(c);
        const box = el("div");
        renderConflicts(box, all);
        out.appendChild(box);
      }
      toast("Generation finished", `${created.length} created, ${skipped.length} skipped.`, "ok");
      return;
    }
    if (status === "FAILED") {
      toast("Generation failed", JSON.stringify(res.body.result), "bad");
      return;
    }
    await new Promise(r => setTimeout(r, 600));
  }
}

/* -------------------------------------------------------------- master sheet */

async function sheetStatus(button: HTMLButtonElement): Promise<void> {
  const out = $("sheet-result");
  const res = await withBusy(button, () => api<any>("/master-sheet/status"));
  if (!res.ok) { showResult(out, errorText(res.body), "bad"); return; }

  clear(out);
  const list = el("dl");
  const add = (k: string, v: string) => {
    const row = el("div", "kv");
    row.appendChild(el("dt", undefined, k));
    row.appendChild(el("dd", undefined, v));
    list.appendChild(row);
  };
  add("Backend", res.body.backend);
  add("Mirrored rows", String((res.body.mirrored ?? []).reduce((n: number, m: any) => n + m.bookings, 0)));
  out.appendChild(list);
  if (res.body.backend === "none") {
    out.appendChild(el("div", "result info",
      "No sheet configured. Set MASTER_SHEET_BACKEND to csv or google on the server."));
  }
}

async function sheetSync(button: HTMLButtonElement): Promise<void> {
  const out = $("sheet-result");
  const res = await withBusy(button, () => api<any>("/master-sheet/sync", { method: "POST" }));
  if (!res.ok) { showResult(out, errorText(res.body), "bad"); return; }
  pop(button);
  const r = res.body;
  showResult(out, `${r.synced} synced, ${r.removed} removed, ${r.rejected.length} rejected.`,
    r.rejected.length ? "bad" : "ok");
  toast("Master sheet synced", `${r.synced} bookings mirrored.`, "ok");
}

/* --------------------------------------------------------------------- tabs */

function currentTab(): string {
  const active = document.querySelector<HTMLElement>(".tab[aria-selected='true']");
  return active?.dataset.tab ?? "book";
}

function selectTab(name: string): void {
  document.querySelectorAll<HTMLElement>(".tab").forEach(t => {
    t.setAttribute("aria-selected", String(t.dataset.tab === name));
  });
  document.querySelectorAll<HTMLElement>(".tabpanel").forEach(p => {
    p.classList.toggle("is-active", p.dataset.panel === name);
  });
}

/* --------------------------------------------------------------------- wire */

function defaultTimes(): void {
  const start = new Date();
  start.setDate(start.getDate() + 1);
  start.setHours(18, 0, 0, 0);
  const end = new Date(start.getTime() + 60 * 60000);
  const local = (d: Date) => {
    const pad = (n: number) => String(n).padStart(2, "0");
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}:00`;
  };
  ($("b-start") as HTMLInputElement).value = local(start);
  ($("b-end") as HTMLInputElement).value = local(end);
}

/** Keep the end time an hour after the start unless the user overrides it. */
function bindTimeCoupling(): void {
  const start = $("b-start") as HTMLInputElement;
  const end = $("b-end") as HTMLInputElement;
  let touched = false;
  end.addEventListener("input", () => { touched = true; });
  start.addEventListener("change", () => {
    if (touched) return;
    const d = new Date(start.value);
    if (isNaN(d.getTime())) return;
    const e = new Date(d.getTime() + 60 * 60000);
    const pad = (n: number) => String(n).padStart(2, "0");
    end.value = `${e.getFullYear()}-${pad(e.getMonth() + 1)}-${pad(e.getDate())}T${pad(e.getHours())}:${pad(e.getMinutes())}:00`;
  });
}

function onClick(id: string, fn: (b: HTMLButtonElement) => void): void {
  const b = $(id) as HTMLButtonElement;
  b.addEventListener("click", () => fn(b));
}

function init(): void {
  document.querySelectorAll<HTMLElement>(".tab").forEach(tab => {
    tab.addEventListener("click", () => selectTab(tab.dataset.tab!));
  });

  onClick("login-submit", signIn);
  onClick("book-submit", book);
  onClick("roster-submit", addPlayer);
  onClick("generate-submit", generate);
  onClick("sheet-status", sheetStatus);
  onClick("sheet-sync", sheetSync);
  $("signout").addEventListener("click", signOut);

  ($("b-sport") as HTMLSelectElement).addEventListener("change", syncTeamOptions);
  ($("b-home") as HTMLSelectElement).addEventListener("change", () => {
    const home = $("b-home") as HTMLSelectElement;
    const away = $("b-away") as HTMLSelectElement;
    if (home.value === away.value && away.options.length > 1) {
      away.selectedIndex = (away.selectedIndex + 1) % away.options.length;
    }
  });

  // Enter submits the sign-in form, as everyone expects it to.
  for (const id of ["login-email", "login-password"]) {
    $(id).addEventListener("keydown", (e) => {
      if ((e as KeyboardEvent).key === "Enter") ($("login-submit") as HTMLButtonElement).click();
    });
  }

  defaultTimes();
  bindTimeCoupling();
  renderSession();
  renderDrafts();
  loadReference();
  loadSchedule();
  setInterval(loadSchedule, 6000);
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", init);
} else {
  init();
}

