1	/* ============================================================================
2	   Intramural Scheduler — Onyx + Candy Blue
3	   Hand-written CSS. No framework, no reset library, no build step.
4	
5	   The palette is deliberately almost monochrome. Candy Blue is spent on
6	   exactly one thing per view — the action you are most likely to want — so
7	   that it actually reads as special (Von Restorff). Everything that is merely
8	   available is onyx and grey.
9	   ========================================================================= */
10	
11	:root {
12	  /* Onyx ramp — surfaces, darkest to lightest */
13	  --onyx-900: #0b0d10;
14	  --onyx-800: #101317;
15	  --onyx-700: #161a20;
16	  --onyx-600: #1c212a;
17	  --onyx-500: #232936;
18	  --line:     #2b3240;
19	  --line-soft:#212734;
20	
21	  /* Candy Blue — the single accent */
22	  --candy-400: #63c9ff;
23	  --candy-500: #2bb3ff;
24	  --candy-600: #0d98e8;
25	  --candy-700: #0a7ab9;
26	  --candy-glow: rgba(43, 179, 255, 0.32);
27	  --candy-wash: rgba(43, 179, 255, 0.10);
28	
29	  /* Text */
30	  --text:      #e9edf4;
31	  --text-dim:  #9aa6b8;
32	  --text-faint:#6b7687;
33	  --on-candy:  #04202f;
34	
35	  /* Semantic — each conflict kind gets its own hue so they are told apart
36	     at a glance rather than by reading the label. */
37	  --ok:        #3ddc97;
38	  --ok-wash:   rgba(61, 220, 151, 0.12);
39	  --venue:     #ff6b6b;   /* venue clash */
40	  --venue-wash:rgba(255, 107, 107, 0.12);
41	  --player:    #ffb454;   /* double-booked player */
42	  --player-wash:rgba(255, 180, 84, 0.12);
43	  --blackout:  #b79cff;   /* not a clash — not enough rest */
44	  --blackout-wash: rgba(183, 156, 255, 0.13);
45	
46	  --radius:   10px;
47	  --radius-sm: 7px;
48	  --radius-lg: 14px;
49	
50	  /* Fitts's Law: nothing interactive is smaller than this. */
51	  --tap: 44px;
52	
53	  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto,
54	          Helvetica, Arial, sans-serif;
55	  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
56	
57	  /* One spring, used everywhere, so every press feels like the same product */
58	  --spring: cubic-bezier(0.34, 1.56, 0.64, 1);
59	  --ease:   cubic-bezier(0.4, 0, 0.2, 1);
60	}
61	
62	* { box-sizing: border-box; }
63	
64	html, body { height: 100%; }
65	
66	body {
67	  margin: 0;
68	  background: var(--onyx-900);
69	  color: var(--text);
70	  font-family: var(--sans);
71	  font-size: 15px;
72	  line-height: 1.55;
73	  -webkit-font-smoothing: antialiased;
74	}
75	
76	h1, h2, h3, p { margin: 0; }
77	
78	button, input, select, textarea { font: inherit; color: inherit; }
79	
80	:focus-visible {
81	  outline: 2px solid var(--candy-500);
82	  outline-offset: 2px;
83	  border-radius: 4px;
84	}
85	
86	/* ---------------------------------------------------------------- app bar */
87	
88	.appbar {
89	  position: sticky;
90	  top: 0;
91	  z-index: 40;
92	  display: flex;
93	  align-items: center;
94	  justify-content: space-between;
95	  gap: 16px;
96	  padding: 0 20px;
97	  height: 60px;
98	  background: rgba(16, 19, 23, 0.86);
99	  backdrop-filter: blur(12px);
100	  border-bottom: 1px solid var(--line);
101	}
102	
103	.brand { display: flex; align-items: center; gap: 11px; min-width: 0; }
104	
105	.brand-mark {
106	  width: 30px; height: 30px;
107	  border-radius: 9px;
108	  display: grid; place-items: center;
109	  background: linear-gradient(145deg, var(--candy-400), var(--candy-600));
110	  color: var(--on-candy);
111	  font-weight: 800;
112	  font-size: 14px;
113	  letter-spacing: -0.5px;
114	  box-shadow: 0 3px 14px var(--candy-glow);
115	  flex: none;
116	}
