/**
 * Headless smoke test for frontend/app.js.
 *
 * Stubs just enough DOM for the app to run, but lets `fetch` hit the REAL
 * backend on :8000. So this exercises the actual request/response wiring —
 * login, reference data, booking, conflicts — without a browser.
 */
import { readFileSync } from "node:fs";

const HTML = readFileSync(new URL("../../../../../Users/varun/Developer/software design practical /frontend/index.html", import.meta.url), "utf8");
const JS = readFileSync(new URL("../../../../../Users/varun/Developer/software design practical /frontend/app.js", import.meta.url), "utf8");

const ids = [...HTML.matchAll(/id="([^"]+)"/g)].map(m => m[1]);
const errors = [];
const nodesById = new Map();

class El {
  constructor(tag = "div", id = "") {
    this.tagName = (tag || "div").toUpperCase();
    this.id = id;
    this.children = [];
    this.childNodes = [];
    this._cls = new Set();
    this._attrs = new Map();
    this._listeners = new Map();
    this.dataset = {};
    this.style = {};
    this.textContent = "";
    this.value = "";
    this.hidden = false;
    this.disabled = false;
    this.options = [];
    this.selectedIndex = -1;
    this.offsetWidth = 1;
    this.type = "";
    this.spellcheck = false;
  }
  get className() { return [...this._cls].join(" "); }
  set className(v) { this._cls = new Set(String(v).split(/\s+/).filter(Boolean)); }
  get classList() {
    const s = this._cls;
    return {
      add: (...c) => c.forEach(x => s.add(x)),
      remove: (...c) => c.forEach(x => s.delete(x)),
      contains: c => s.has(c),
      toggle: (c, force) => {
        const on = force === undefined ? !s.has(c) : !!force;
        on ? s.add(c) : s.delete(c);
        return on;
      },
    };
  }
  get firstChild() { return this.childNodes[0] ?? null; }
  get lastElementChild() { return this.children[this.children.length - 1] ?? null; }
  appendChild(n) { this.children.push(n); this.childNodes.push(n); n.parentNode = this; return n; }
  append(...xs) {
    for (const x of xs) {
      if (typeof x === "string") this.childNodes.push({ text: x });
      else this.appendChild(x);
    }
  }
  removeChild(n) {
    this.children = this.children.filter(c => c !== n);
    this.childNodes = this.childNodes.filter(c => c !== n);
    return n;
  }
  remove() { this.parentNode?.removeChild(this); }
  addEventListener(t, fn) {
    if (!this._listeners.has(t)) this._listeners.set(t, []);
    this._listeners.get(t).push(fn);
  }
  dispatch(t, ev = {}) {
    for (const fn of this._listeners.get(t) ?? []) fn({ stopPropagation() {}, preventDefault() {}, ...ev });
  }
  setAttribute(k, v) { this._attrs.set(k, String(v)); }
  getAttribute(k) { return this._attrs.get(k) ?? null; }
  querySelector(sel) { return this.querySelectorAll(sel)[0] ?? null; }
  querySelectorAll(sel) {
    const want = sel.split(",").map(s => s.trim().replace(/^\./, ""));
    const hits = [];
    const walk = n => {
      for (const c of n.children) {
        if (want.some(w => c._cls.has(w.split(" ").pop().replace(/^\./, "")))) hits.push(c);
        walk(c);
      }
    };
    walk(this);
    return hits;
  }
}

const root = new El("body");
for (const id of ids) {
  const node = new El("div", id);
  nodesById.set(id, node);
  root.appendChild(node);
}
// tabs/panels the app queries by class
for (const [tab, panel] of [["book","book"],["drafts","drafts"],["roster","roster"],["generate","generate"],["admin","admin"]]) {
  const t = new El("button"); t.className = "tab"; t.dataset.tab = tab; root.appendChild(t);
  const p = new El("div"); p.className = "tabpanel"; p.dataset.panel = panel; root.appendChild(p);
}

global.document = {
  readyState: "complete",
  getElementById: id => nodesById.get(id) ?? null,
  createElement: tag => new El(tag),
  querySelector: s => root.querySelector(s),
  querySelectorAll: s => root.querySelectorAll(s),
  addEventListener: () => {},
  body: root,
};
global.Option = class { constructor(text, value) { this.text = text; this.value = value; this._cls = new Set(); } };
global.location = { search: "", port: "8080", origin: "http://127.0.0.1:8080" };
global.requestAnimationFrame = fn => setTimeout(fn, 0);
global.window = global;

const realSetInterval = global.setInterval;
global.setInterval = () => 0;                 // don't keep the process alive

process.on("uncaughtException", e => { errors.push("uncaught: " + e.message); });
process.on("unhandledRejection", e => { errors.push("unhandled: " + (e?.message ?? e)); });

// ---- run the app ----------------------------------------------------------
try {
  const mod = new Function(JS + "\n;return { signIn, book, state, selectTab, renderDrafts };");
  var app = mod();
} catch (e) {
  console.log("FAIL: app.js threw while loading —", e.message);
  process.exit(1);
}

console.log("✓ app.js loaded and init() ran without throwing");

// Give the async loads (reference data + schedule) time against the real API.
await new Promise(r => setTimeout(r, 1500));

const sportSel = nodesById.get("b-sport");
const homeSel = nodesById.get("b-home");
const venueSel = nodesById.get("b-venue");
console.log(`✓ sports loaded from API: ${sportSel.children.length} option(s)`);
console.log(`✓ teams loaded for sport:  ${homeSel.children.length} option(s)`);
console.log(`✓ venues loaded:           ${venueSel.children.length} option(s)`);
console.log(`✓ matches pulled:          ${app.state.matches.length}`);
console.log(`✓ calendar cells rendered: ${nodesById.get("calendar").children.length}`);

if (errors.length) {
  console.log("\nRUNTIME ERRORS:");
  for (const e of errors) console.log("  ✗ " + e);
  process.exit(1);
}
console.log("\n=== NO RUNTIME ERRORS ===");
process.exit(0);

