import { readFileSync } from "node:fs";

const HTML = readFileSync(new URL("../../../../../Users/varun/Developer/software design practical /frontend/index.html", import.meta.url), "utf8");
const JS = readFileSync(new URL("../../../../../Users/varun/Developer/software design practical /frontend/app.js", import.meta.url), "utf8");

const ids = [...HTML.matchAll(/id="([^"]+)"/g)].map(m => m[1]);
const errors = [];
const nodesById = new Map();

class El {
  constructor(tag = "div", id = "") {
    this.tagName = (tag || "div").toUpperCase();
    this.id = id;
    this.children = [];
    this.childNodes = [];
    this._cls = new Set();
    this._attrs = new Map();
    this._listeners = new Map();
    this.dataset = {};
    this.style = {};
    this.textContent = "";
    this.value = "";
    this.hidden = false;
    this.disabled = false;
    this.options = [];
    this.selectedIndex = -1;
    this.offsetWidth = 1;
    this.type = "";
    this.spellcheck = false;
  }
  get className() { return [...this._cls].join(" "); }
  set className(v) { this._cls = new Set(String(v).split(/\s+/).filter(Boolean)); }
  get classList() {
    const s = this._cls;
    return {
      add: (...c) => c.forEach(x => s.add(x)),
      remove: (...c) => c.forEach(x => s.delete(x)),
      contains: c => s.has(c),
      toggle: (c, force) => {
        const on = force === undefined ? !s.has(c) : !!force;
        on ? s.add(c) : s.delete(c);
        return on;
      },
    };
  }
  get firstChild() { return this.childNodes[0] ?? null; }
  get lastElementChild() { return this.children[this.children.length - 1] ?? null; }
  appendChild(n) { this.children.push(n); this.childNodes.push(n); n.parentNode = this; return n; }
  append(...xs) {
    for (const x of xs) {
      if (typeof x === "string") this.childNodes.push({ text: x });
      else this.appendChild(x);
    }
  }
  removeChild(n) {
    this.children = this.children.filter(c => c !== n);
    this.childNodes = this.childNodes.filter(c => c !== n);
    return n;
  }
  remove() { this.parentNode?.removeChild(this); }
  addEventListener(t, fn) {
    if (!this._listeners.has(t)) this._listeners.set(t, []);
    this._listeners.get(t).push(fn);
