console.log(`✓ calendar cells rendered: ${nodesById.get("calendar").children.length}`);

if (errors.length) {
  console.log("\nRUNTIME ERRORS:");
  for (const e of errors) console.log("  ✗ " + e);
  process.exit(1);
}
console.log("\n=== NO RUNTIME ERRORS ===");
process.exit(0);

