    this.tagName = (tag || "div").toUpperCase();
    this.id = id;
    this.children = []; this.childNodes = [];
    this._cls = new Set(); this._attrs = new Map(); this._listeners = new Map();
    this.dataset = {}; this.style = {};
    this.textContent = ""; this.value = "";
    this.hidden = false; this.disabled = false;
    this.options = []; this.selectedIndex = -1;
    this.offsetWidth = 1; this.type = ""; this.spellcheck = false;
  }
  get className() { return [...this._cls].join(" "); }
  set className(v) { this._cls = new Set(String(v).split(/\s+/).filter(Boolean)); }
  get classList() {
    const s = this._cls;
    return {
      add: (...c) => c.forEach(x => s.add(x)),
      remove: (...c) => c.forEach(x => s.delete(x)),
      contains: c => s.has(c),
      toggle: (c, force) => {
        const on = force === undefined ? !s.has(c) : !!force;
        if (on) s.add(c); else s.delete(c);
        return on;
      },
    };
  }
  get firstChild() { return this.childNodes[0] ?? null; }
  get lastElementChild() { return this.children[this.children.length - 1] ?? null; }
  appendChild(n) {
    this.children.push(n); this.childNodes.push(n); n.parentNode = this;
    const isOption = n && !n.tagName && n.text !== undefined && n.value !== undefined;
    if (isOption) {
      this.options.push(n);
      if (this.options.length === 1) { this.value = n.value; this.selectedIndex = 0; }
    }
    return n;
  }
  append(...xs) {
    for (const x of xs) {
      if (typeof x === "string") this.childNodes.push({ text: x, children: [] });
      else this.appendChild(x);
    }
  }
  removeChild(n) {
    this.children = this.children.filter(c => c !== n);
    this.childNodes = this.childNodes.filter(c => c !== n);
    this.options = this.options.filter(c => c !== n);
    if (this.options.length === 0) { this.value = ""; this.selectedIndex = -1; }
    return n;
  }
  remove() { if (this.parentNode) this.parentNode.removeChild(this); }
  addEventListener(t, fn) {
    if (!this._listeners.has(t)) this._listeners.set(t, []);
    this._listeners.get(t).push(fn);
  }
  setAttribute(k, v) { this._attrs.set(k, String(v)); }
  getAttribute(k) { return this._attrs.get(k) ?? null; }
  querySelector(sel) { return this.querySelectorAll(sel)[0] ?? null; }
  querySelectorAll(sel) {
    const want = sel.split(",").map(s => s.trim().split(/\s+/).pop().replace(/^\./, ""));
    const hits = [];
    const walk = n => {
      for (const c of (n.children ?? [])) {
        if (c._cls && want.some(w => c._cls.has(w))) hits.push(c);
        walk(c);
      }
    };
    walk(this);
    return hits;
  }
}

const root = new El("body");
for (const id of ids) {
  const node = new El("div", id);
  nodesById.set(id, node);
  root.appendChild(node);
}
for (const name of ["book", "drafts", "roster", "generate", "admin"]) {
  const t = new El("button"); t.className = "tab"; t.dataset.tab = name; root.appendChild(t);
  const p = new El("div"); p.className = "tabpanel"; p.dataset.panel = name; root.appendChild(p);
}

global.document = {
  readyState: "complete",
  getElementById: id => nodesById.get(id) ?? null,
  createElement: tag => new El(tag),
  querySelector: s => root.querySelector(s),
  querySelectorAll: s => root.querySelectorAll(s),
  addEventListener: () => {},
  body: root,
};
global.Option = class {
  constructor(text, value) {
    this.text = text; this.value = value;
    this._cls = new Set(); this.children = []; this.childNodes = [];
  }
};
global.location = { search: "", port: "8080", origin: "http://127.0.0.1:8080" };
global.requestAnimationFrame = fn => setTimeout(fn, 0);
global.window = global;
global.setInterval = () => 0;

process.on("uncaughtException", e => errors.push("uncaught: " + e.message));
process.on("unhandledRejection", e => errors.push("unhandled: " + (e && e.message ? e.message : e)));

const app = new Function(
  JS + "\n;return { signIn, book, addPlayer, state, selectTab, renderDrafts };"
)();
console.log("PASS  app.js loaded, init() ran without throwing");

const wait = ms => new Promise(r => setTimeout(r, ms));
await wait(1200);

const setv = (id, v) => { nodesById.get(id).value = v; };
const btn = () => new El("button");

console.log("PASS  reference data: " +
  nodesById.get("b-sport").options.length + " sports, " +
  nodesById.get("b-home").options.length + " teams, " +
  nodesById.get("b-venue").options.length + " venues");
console.log("PASS  calendar rendered " + nodesById.get("calendar").children.length + " cells");

setv("login-email", "head@example.edu");
setv("login-password", "head-pass");
await app.signIn(btn());
await wait(400);
console.log(app.state.session
  ? "PASS  signed in as " + app.state.session.role
  : "FAIL  sign-in did not establish a session");

setv("p-name", "Pashi"); setv("p-roll", "R900");
nodesById.get("p-team").value = "1";
await app.addPlayer(btn());
await wait(300);

setv("b-start", "2026-11-20T19:30:00");
setv("b-end", "2026-11-20T20:30:00");
await app.book(btn());
await wait(400);
console.log(app.state.drafts.length
  ? "PASS  booked draft #" + app.state.drafts[0].id + " filed under " + app.state.drafts[0].term
  : "FAIL  booking produced no draft");

// Same players, 30 minutes later: must surface a blackout in the DOM.
setv("b-start", "2026-11-20T21:00:00");
setv("b-end", "2026-11-20T22:00:00");
await app.book(btn());
await wait(400);

const kinds = [];
const walk = n => {
  for (const c of (n.children ?? [])) {
    if (c._cls) for (const cl of c._cls) if (cl.startsWith("c-")) kinds.push(cl);
    walk(c);
  }
};
walk(nodesById.get("book-result"));
const unique = [...new Set(kinds)];
console.log(unique.length
  ? "PASS  conflict panel rendered in the DOM: " + unique.join(", ")
  : "FAIL  conflict returned by API but nothing rendered");

if (errors.length) {
  console.log("\nRUNTIME ERRORS:");
  for (const e of errors) console.log("  FAIL  " + e);
  process.exit(1);
}
console.log("\n=== NO RUNTIME ERRORS ===");
process.exit(0);

