32	    this.options = [];
33	    this.selectedIndex = -1;
34	    this.offsetWidth = 1;
35	    this.type = "";
36	    this.spellcheck = false;
37	  }
38	  get className() { return [...this._cls].join(" "); }
39	  set className(v) { this._cls = new Set(String(v).split(/\s+/).filter(Boolean)); }
40	  get classList() {
41	    const s = this._cls;
42	    return {
43	      add: (...c) => c.forEach(x => s.add(x)),
44	      remove: (...c) => c.forEach(x => s.delete(x)),
45	      contains: c => s.has(c),
46	      toggle: (c, force) => {
47	        const on = force === undefined ? !s.has(c) : !!force;
48	        on ? s.add(c) : s.delete(c);
49	        return on;
50	      },
51	    };
52	  }
53	  get firstChild() { return this.childNodes[0] ?? null; }
54	  _resetIfEmpty() { if (this.options.length === 0) { this.value = ""; this.selectedIndex = -1; } }
55	  get lastElementChild() { return this.children[this.children.length - 1] ?? null; }
56	  appendChild(n) {
57	    this.children.push(n); this.childNodes.push(n); n.parentNode = this;
58	    if (n && !n.tagName && n.text !== undefined && n.value !== undefined) { this.options.push(n); if (this.options.length === 1) { this.value = n.value; this.selectedIndex = 0; } }
59	    return n;
60	  }
61	  append(...xs) {
62	    for (const x of xs) {
63	      if (typeof x === "string") this.childNodes.push({ text: x });
64	      else this.appendChild(x);
65	    }
66	  }
67	  removeChild(n) {
68	    this.children = this.children.filter(c => c !== n);
69	    this.options = this.options.filter(c => c !== n);
70	    this.childNodes = this.childNodes.filter(c => c !== n);
71	    return n;
72	  }
73	  remove() { this.parentNode?.removeChild(this); }
74	  addEventListener(t, fn) {
75	    if (!this._listeners.has(t)) this._listeners.set(t, []);
76	    this._listeners.get(t).push(fn);
77	  }
78	  dispatch(t, ev = {}) {
79	    for (const fn of this._listeners.get(t) ?? []) fn({ stopPropagation() {}, preventDefault() {}, ...ev });
80	  }
81	  setAttribute(k, v) { this._attrs.set(k, String(v)); }
82	  getAttribute(k) { return this._attrs.get(k) ?? null; }
83	  querySelector(sel) { return this.querySelectorAll(sel)[0] ?? null; }
