// Which [hidden] elements are defeated by an author `display` rule?
const broken=[...document.querySelectorAll('[hidden]')].map(e=>({
  id:e.id||e.className,
  computedDisplay:getComputedStyle(e).display,
  stillRendered:e.getBoundingClientRect().width>0
}));
// prove the cause
const tb=document.getElementById('term-badge');
JSON.stringify({
  hiddenElements: broken,
  cause: "author rule sets display, beating the UA [hidden]{display:none}",
  termBadgeComputed: getComputedStyle(tb).display,
  fixWorks: (()=>{const s=document.createElement('style');
    s.textContent='[hidden]{display:none !important}';document.head.appendChild(s);
    const after=[...document.querySelectorAll('[hidden]')].map(e=>({id:e.id||e.className,rendered:e.getBoundingClientRect().width>0}));
    s.remove(); return after;})()
},null,1)

