p="frontend/styles.css"; s=open(p).read()

# 1. [hidden] must beat author display rules.
s=s.replace("""* { box-sizing: border-box; }""",
"""* { box-sizing: border-box; }

/* `hidden` has to win. The UA rule is [hidden]{display:none}, which any author
   rule that sets `display` on a class beats — .term-badge{display:inline-flex}
   silently left a stray empty chip in the app bar. Anything toggled with
   el.hidden needs this to actually disappear. */
[hidden] { display: none !important; }""")

# 2. Toasts must not sit on top of the primary action in the rail.
s=s.replace("""  max-width: min(380px, calc(100vw - 36px));
}""",
"""  max-width: min(380px, calc(100vw - 36px));
  /* Never cover the rail's primary button: toasts are confirmations, and a
     confirmation that hides the next action is worse than no confirmation. */
  pointer-events: none;
}
.toast { pointer-events: auto; }
@media (min-width: 1041px) {
  .toasts { right: calc(400px + 34px); }
}""")
open(p,"w").write(s)
print("styles.css: [hidden] fix + toast no longer covers the CTA")
PYEOF
grep -n "hidden] { display" frontend/styles.css && grep -n "right: calc(400px" frontend/styles.css

