1	/**
2	 * Intramural Scheduler — frontend.
3	 *
4	 * TypeScript, zero dependencies. Compiled to ../app.js by ../build.mjs using
5	 * Node's own `module.stripTypeScriptTypes`; nothing is installed.
6	 *
7	 * Because types are *stripped* rather than transformed, this file avoids the
8	 * constructs that need real codegen: no `enum`, no `namespace`, no constructor
9	 * parameter properties. Union types and `as const` cover the same ground and
10	 * survive stripping untouched.
11	 */
12	
13	const API = (() => {
14	  const override = new URLSearchParams(location.search).get("api");
15	  if (override) return override.replace(/\/$/, "");
16	  if (location.port === "8000") return location.origin;
17	  return "http://127.0.0.1:8000";
18	})();
19	
20	/* ------------------------------------------------------------------- types */
21	
22	type Role = "HEAD" | "REP" | "VIEWER";
23	
24	interface Session { token: string; role: Role; sportScope: string | null; email: string; }
25	interface Team { id: number; name: string; sport: string; season_id: number; }
26	interface Venue { id: number; name: string; location: string | null; }
27	interface Season { id: number; sport: string; start_date: string; end_date: string; }
28	interface Term { id: number; label: string; start_date: string; end_date: string; is_current: number; }
29	
30	interface Match {
31	  id: number; home_team_id: number; away_team_id: number; venue_id: number;
32	  start_time: string; end_time: string; status: string; sport: string;
33	  season_id: number; version: number;
34	}
35	
36	interface RosterEntry { id: number; name: string; roll_number: string; sport: string; }
37	
38	interface Assignment {
39	  id: number; role: string; sport_scope: string | null; status: string;
40	  nominated_user_id: number; term_id: number;
41	}
42	
43	interface Conflict {
44	  type: "venue" | "player" | "blackout" | "venue_external"
45	      | "player_external" | "blackout_external" | "invalid";
46	  player_name?: string; conflicting_match_id?: number;
47	  rest_minutes?: number; required_minutes?: number;
48	  description?: string; external_ref?: string; source?: string; reason?: string;
49	}
50	
51	interface Draft { id: number; version: number; label: string; when: string; term: string; }
52	interface ApiResult<T> { ok: boolean; status: number; body: T; }
53	
54	/* --------------------------------------------------------------- app state */
55	
56	const state: {
57	  session: Session | null;
58	  teams: Team[]; venues: Venue[]; seasons: Season[];
59	  drafts: Draft[]; matches: Match[];
60	  month: Date; selected: Match | null;
61	  loadedOnce: boolean;
62	} = {
63	  session: null,
64	  teams: [], venues: [], seasons: [],
65	  drafts: [], matches: [],
66	  month: new Date(new Date().getFullYear(), new Date().getMonth(), 1),
67	  selected: null,
68	  loadedOnce: false,
69	};
70	
71	/* ------------------------------------------------------------------ helpers */
72	
73	function $<T extends HTMLElement>(id: string): T {
74	  const el = document.getElementById(id);
75	  if (!el) throw new Error(`missing element #${id}`);
76	  return el as T;
77	}
78	
79	function maybe<T extends HTMLElement>(id: string): T | null {
80	  return document.getElementById(id) as T | null;
81	}
82	
83	function el<K extends keyof HTMLElementTagNameMap>(
84	  tag: K, className?: string, text?: string
85	): HTMLElementTagNameMap[K] {
86	  const node = document.createElement(tag);
87	  if (className) node.className = className;
88	  if (text !== undefined) node.textContent = text;
89	  return node;
90	}
91	
92	function clear(node: HTMLElement): void {
93	  while (node.firstChild) node.removeChild(node.firstChild);
94	}
95	
96	function val(id: string): string {
97	  return ($(id) as HTMLInputElement | HTMLSelectElement).value;
98	}
99	
100	async function api<T = any>(path: string, options: RequestInit = {}): Promise<ApiResult<T>> {
101	  const headers: Record<string, string> = { "Content-Type": "application/json" };
102	  if (state.session) headers["Authorization"] = `Bearer ${state.session.token}`;
103	  try {
104	    const res = await fetch(API + path, {
105	      ...options, headers: { ...headers, ...(options.headers as Record<string, string>) },
106	    });
107	    let body: any = null;
108	    try { body = await res.json(); } catch { body = null; }
109	    return { ok: res.ok, status: res.status, body: body as T };
110	  } catch {
111	    return { ok: false, status: 0,
112	      body: { detail: "Cannot reach the API. Is the backend running?" } as any };
113	  }
114	}
115	
116	function errorText(body: any): string {
117	  if (!body) return "Something went wrong.";
118	  if (typeof body.detail === "string") return body.detail;
119	  if (Array.isArray(body.detail)) return body.detail.map((d: any) => d.msg || String(d)).join("; ");
120	  if (body.detail) return JSON.stringify(body.detail);
121	  return JSON.stringify(body);
122	}
123	
124	/** Stored times are canonical UTC; show them in the viewer's own zone. */
125	function fmtTime(iso: string): string {
126	  const d = new Date(iso);
127	  return isNaN(d.getTime()) ? iso : d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
128	}
129	
130	function fmtDay(iso: string): string {
131	  const d = new Date(iso);
132	  return isNaN(d.getTime()) ? iso
133	    : d.toLocaleDateString([], { weekday: "short", day: "numeric", month: "short" });
134	}
135	
136	function durationMins(a: string, b: string): number {
137	  return Math.round((new Date(b).getTime() - new Date(a).getTime()) / 60000);
138	}
139	
140	function teamName(id: number): string {
141	  const t = state.teams.find(x => x.id === id);
142	  return t ? t.name : `Team ${id}`;
143	}
144	
145	function venueName(id: number): string {
146	  const v = state.venues.find(x => x.id === id);
147	  return v ? v.name : `Venue ${id}`;
148	}
149	
150	function pad(n: number): string { return String(n).padStart(2, "0"); }
151	
152	function localIso(d: Date): string {
153	  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}` +
154	         `T${pad(d.getHours())}:${pad(d.getMinutes())}:00`;
155	}
156	
157	/* -------------------------------------------------------------------- toast */
158	
159	function toast(title: string, body?: string, kind: "ok" | "bad" | "info" = "info"): void {
160	  const wrap = $("toasts");
161	  const node = el("div", `toast ${kind}`);
162	  node.appendChild(el("div", "toast-bar"));
163	  const col = el("div");
164	  col.appendChild(el("div", "toast-title", title));
165	  if (body) col.appendChild(el("div", "toast-body", body));
166	  node.appendChild(col);
167	  wrap.appendChild(node);
168	  setTimeout(() => {
169	    node.classList.add("is-leaving");
170	    setTimeout(() => node.remove(), 240);
171	  }, 4200);
172	}
173	
174	/** Press feedback that outlives the click: a short spring pop on success. */
175	function pop(button: HTMLButtonElement): void {
176	  button.classList.remove("did-succeed");
177	  void button.offsetWidth;                       // restart the animation
178	  button.classList.add("did-succeed");
179	  setTimeout(() => button.classList.remove("did-succeed"), 460);
180	}
181	
182	async function withBusy<T>(button: HTMLButtonElement, work: () => Promise<T>): Promise<T> {
183	  button.classList.add("is-busy");
184	  button.disabled = true;
185	  try { return await work(); }
186	  finally { button.classList.remove("is-busy"); button.disabled = false; }
187	}
188	
189	function showResult(host: HTMLElement, text: string, kind: "ok" | "bad" | "info"): void {
190	  clear(host);
191	  host.appendChild(el("div", `result ${kind}`, text));
192	}
193	
194	function emptyState(mark: string, title: string, body: string): HTMLElement {
195	  const wrap = el("div", "empty");
196	  wrap.appendChild(el("div", "empty-mark", mark));
197	  wrap.appendChild(el("div", "empty-title", title));
198	  wrap.appendChild(el("div", "empty-body", body));
199	  return wrap;
200	}
201	
202	/* ---------------------------------------------------------------- conflicts
203	   Plain language, because the point is to tell the organizer what to DO next. */
204	

