import os, sqlite3, subprocess, sys
# 1. fresh database
for f in ("fresh.db","fresh.db-wal","fresh.db-shm","legacy.db","legacy.db-wal","legacy.db-shm"):
    if os.path.exists(f): os.remove(f)
os.environ["SCHEDULER_DB_PATH"]="fresh.db"
subprocess.run([sys.executable,"-c","from app.db import init_db; init_db()"],check=True,capture_output=True,env=os.environ)

# 2. legacy database: pre-audit schema, then migrated by init_db()
legacy=sqlite3.connect("legacy.db")
legacy.executescript("""
CREATE TABLE venues (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, location TEXT, capacity INTEGER);
CREATE TABLE external_bookings (id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT NOT NULL,
  external_ref TEXT NOT NULL, venue_id INTEGER, venue_name TEXT, start_time TEXT NOT NULL,
  end_time TEXT NOT NULL, description TEXT, synced_at TEXT NOT NULL, UNIQUE(source, external_ref));
INSERT INTO venues (name) VALUES ('Legacy Court');
""")
legacy.commit(); legacy.close()
os.environ["SCHEDULER_DB_PATH"]="legacy.db"
r=subprocess.run([sys.executable,"-c","from app.db import init_db; init_db()"],capture_output=True,text=True,env=os.environ)
print("migration of a legacy db:", "OK" if r.returncode==0 else "FAILED\n"+r.stderr[-400:])

def cols(db, table):
