input.content:
/* ============================================================================
   Intramural Scheduler — Onyx + Candy Blue
   Hand-written CSS. No framework, no reset library.

   Palette and motion curve are unchanged from the previous revision; this file
   restructures layout and material only. See design.md for the reasoning
   behind every rule that looks like a preference.
   ========================================================================= */

:root {
  /* Onyx ramp — surfaces, darkest to lightest */
  --onyx-900: #0b0d10;
  --onyx-800: #101317;
  --onyx-700: #161a20;
  --onyx-600: #1c212a;
  --onyx-500: #232936;
  --line:     #2b3240;
  --line-soft:#212734;

  /* Candy Blue — the single accent */
  --candy-400: #63c9ff;
  --candy-500: #2bb3ff;
  --candy-600: #0d98e8;
  --candy-700: #0a7ab9;
  --candy-glow: rgba(43, 179, 255, 0.32);
  --candy-wash: rgba(43, 179, 255, 0.10);

  /* Text */
  --text:      #e9edf4;
  --text-dim:  #9aa6b8;
  --text-faint:#6b7687;
  --on-candy:  #04202f;

  /* Status — reserved, never decoration. Each says what to DO. */
  --ok:        #3ddc97;
  --ok-wash:   rgba(61, 220, 151, 0.12);
  --venue:     #ff6b6b;
  --venue-wash:rgba(255, 107, 107, 0.12);
  --player:    #ffb454;
  --player-wash:rgba(255, 180, 84, 0.12);
  --blackout:  #b79cff;
  --blackout-wash: rgba(183, 156, 255, 0.13);

  --radius:    12px;
  --radius-sm: 8px;
  --radius-lg: 16px;

  /* Fitts's Law: nothing interactive is smaller than this. */
  --tap: 44px;

  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto,
          Helvetica, Arial, sans-serif;
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;

  --spring: cubic-bezier(0.34, 1.56, 0.64, 1);
  --ease:   cubic-bezier(0.4, 0, 0.2, 1);

  --nav-h: 62px;
}

* { box-sizing: border-box; }

/* `hidden` has to win. The UA rule is [hidden]{display:none}, which any author
   rule setting `display` on a class beats — that silently left a stray empty
   chip in the app bar once already. */
[hidden] { display: none !important; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  min-height: 100%;
  background: var(--onyx-900);
  color: var(--text);
  font-family: var(--sans);
  font-size: 15px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

/* A faint field behind everything, so the glass has something to refract.
   Without it, "liquid glass" over flat black is indistinguishable from flat
   black. */
body::before {
  content: "";
  position: fixed;
  inset: -10%;
  z-index: -1;
  pointer-events: none;
  background:
    radial-gradient(48rem 30rem at 12% -8%, rgba(43,179,255,0.16), transparent 62%),
    radial-gradient(36rem 26rem at 92% 4%, rgba(99,201,255,0.10), transparent 58%),
    radial-gradient(40rem 28rem at 70% 96%, rgba(43,179,255,0.07), transparent 60%);
}

h1, h2, h3, p { margin: 0; }
button, input, select, textarea { font: inherit; color: inherit; }

:focus-visible {
  outline: 2px solid var(--candy-500);
  outline-offset: 2px;
  border-radius: 5px;
}

.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

/* ======================================================= nav bar — glass ===
   backdrop-filter with an SVG filter reference is NOT universally supported;
   Chrome parsed and silently dropped it for years. Verified rendering in
   Chrome 154 before this shipped. The blur is in the same declaration so a
   browser that ignores the url() still frosts the bar. */

.appbar {
  position: sticky;
  top: 0;
  z-index: 60;
  display: flex;
  align-items: center;
  gap: 18px;
  height: var(--nav-h);
  padding: 0 20px;
  background: rgba(16, 19, 23, 0.62);
  backdrop-filter: blur(18px) saturate(150%);
  border-bottom: 1px solid var(--line);
  /* the lit edge — one pixel of white along the top, which is what makes
     glass read as glass rather than fog */
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.30),
              0 8px 32px rgba(0, 0, 0, 0.42);
}

@supports (backdrop-filter: url(#glass-nav)) {
  .appbar { backdrop-filter: url(#glass-nav) blur(16px) saturate(150%); }
}

.brand { display: flex; align-items: center; gap: 11px; flex: none; }

.brand-mark {
  width: 32px; height: 32px;
  border-radius: 10px;
  display: grid; place-items: center;
  background: linear-gradient(145deg, var(--candy-400), var(--candy-600));
  color: var(--on-candy);
  font-weight: 800; font-size: 14px;
  letter-spacing: -0.5px;
  box-shadow: 0 3px 14px var(--candy-glow),
              inset 0 1px 0 rgba(255,255,255,0.45);
}

.brand-name {
  font-size: 15px; font-weight: 650; letter-spacing: -0.2px;
  white-space: nowrap;
}
@media (max-width: 720px) { .brand-name { display: none; } }

/* ------------------------------------------------- the gliding nav pill ---
   No JavaScript. The hovered link claims `anchor-name`, the pill is anchored
   to it, and because the pill's edges are ordinary left/right values a plain
   transition turns each jump into a glide.

   `anchor()` inside the `inset` shorthand does NOT resolve in Chrome 154 —
   only the longhands do. Writing `inset: anchor(...)` produces no positioning
   at all, silently. */

.nav {
  position: relative;
  display: flex;
  align-items: center;
  gap: 2px;
  min-width: 0;
  overflow-x: auto;
  scrollbar-width: none;
}
.nav::-webkit-scrollbar { display: none; }

.nav-link {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  height: 38px;
  padding: 0 14px;
  border: none;
  background: none;
  border-radius: 9px;
  color: var(--text-dim);
  font-size: 13.5px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  transition: color 180ms var(--ease), transform 300ms var(--spring);
}
.nav-link:hover { color: var(--text); }
.nav-link:active { transform: scale(0.94); transition: transform 80ms ease-out; }

/* Selection is not hover. Hover moves the pill; selection colours the label. */
.nav-link[aria-current="page"] { color: var(--candy-400); }

.nav-link:hover { anchor-name: --nav-pill; }

.nav-pill {
  position: absolute;
  z-index: 0;
  position-anchor: --nav-pill;
  left: anchor(left);
  right: anchor(right);
  top: anchor(top);
  bottom: anchor(bottom);
  border-radius: 9px;
  background: rgba(43, 179, 255, 0.14);
  box-shadow: inset 0 0 0 1px rgba(43, 179, 255, 0.34),
              inset 0 1px 0 rgba(255, 255, 255, 0.22);
  opacity: 0;
  pointer-events: none;
  transition:
    left   380ms var(--spring),
    right  380ms var(--spring),
    top    200ms var(--ease),
    bottom 200ms var(--ease),
    opacity 200ms var(--ease);
}
.nav:hover .nav-pill { opacity: 1; }

/* Older engines get no pill rather than a stuck one. */
@supports not (anchor-name: --x) {
  .nav-pill { display: none; }
  .nav-link:hover { background: rgba(43,179,255,0.12); }
}

.appbar-right { display: flex; align-items: center; gap: 10px; margin-left: auto; flex: none; }

.term-badge {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 5px 11px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--onyx-700);
  font-size: 12.5px;
  color: var(--text-dim);
  white-space: nowrap;
}
.term-badge b { color: var(--text); font-weight: 600; }
.term-badge .dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--ok);
  box-shadow: 0 0 0 3px var(--ok-wash);
}
.term-badge.is-break .dot { background: var(--player); box-shadow: 0 0 0 3px var(--player-wash); }
@media (max-width: 960px) { .term-badge { display: none; } }

.session-chip {
  display: flex; align-items: center; gap: 9px;
  padding: 5px 6px 5px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--onyx-700);
  font-size: 12.5px;
  white-space: nowrap;
}
.session-chip .who { color: var(--text); font-weight: 600; }
.session-chip .scope { color: var(--text-faint); }

/* ==================================================================== views */

.view {
  max-width: 1360px;
  margin: 0 auto;
  padding: 22px 20px 64px;
}
.view[hidden] { display: none !important; }

.view-head {
  display: flex; align-items: flex-end; justify-content: space-between;
  gap: 16px; flex-wrap: wrap;
  margin-bottom: 18px;
}
.view-title { font-size: 21px; font-weight: 680; letter-spacing: -0.4px; }
.view-sub { font-size: 13px; color: var(--text-faint); margin-top: 3px; }

.panel {
  background: var(--onyx-800);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.panel-head {
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px;
  padding: 14px 18px;
  border-bottom: 1px solid var(--line-soft);
}
.panel-title { font-size: 13.5px; font-weight: 650; letter-spacing: -0.1px; }
.panel-sub { font-size: 12.5px; color: var(--text-faint); margin-top: 2px; }
.panel-body { padding: 18px; }

/* Proximity does the grouping. Do not add boxes on top of it. */
.group { display: flex; flex-direction: column; gap: 14px; }
.group + .group { margin-top: 26px; padding-top: 22px; border-top: 1px solid var(--line-soft); }
.group-label {
  font-size: 11px; font-weight: 700; letter-spacing: 0.9px;
  text-transform: uppercase; color: var(--text-faint);
  margin-bottom: -4px;
}

.field { display: flex; flex-direction: column; gap: 6px; }
.row2 { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
@media (max-width: 560px) { .row2 { grid-template-columns: 1fr; } }

label { font-size: 12.5px; color: var(--text-dim); font-weight: 550; }

input, select, textarea {
  width: 100%;
  min-height: var(--tap);
  padding: 10px 12px;
  background: var(--onyx-600);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  color: var(--text);
  transition: border-color 140ms var(--ease), box-shadow 140ms var(--ease),
              background-color 140ms var(--ease);
}
input::placeholder { color: var(--text-faint); }
input:hover, select:hover { border-color: #38404f; }
input:focus, select:focus, textarea:focus {
  outline: none;
  border-color: var(--candy-500);
  background: var(--onyx-500);
  box-shadow: 0 0 0 3px var(--candy-wash);
}
select {
  cursor: pointer; appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--text-dim) 50%),
                    linear-gradient(135deg, var(--text-dim) 50%, transparent 50%);
  background-position: calc(100% - 17px) 50%, calc(100% - 12px) 50%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  padding-right: 34px;
}

.hint { font-size: 11.5px; color: var(--text-faint); }

/* =============================================== buttons: press and spring */

.btn {
  position: relative;
  display: inline-flex; align-items: center; justify-content: center;
  gap: 8px;
  min-height: var(--tap);
  padding: 11px 18px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: var(--onyx-500);
  color: var(--text);
  font-size: 14px; font-weight: 600;
  cursor: pointer;
  user-select: none;
  will-change: transform;
  transition: transform 300ms var(--spring),
              background-color 150ms var(--ease),
              border-color 150ms var(--ease),
              box-shadow 200ms var(--ease),
              opacity 150ms var(--ease);
}
.btn:hover { background: #2a3140; }
.btn:active { transform: scale(0.955); transition: transform 80ms ease-out; }
.btn:disabled { opacity: 0.45; cursor: not-allowed; transform: none; }

/* The primary action is glass: translucent candy over a refracted backdrop,
   with the same one-pixel lit edge as the nav. Exactly one per view. */
.btn-primary {
  width: 100%;
  background: color-mix(in srgb, var(--candy-500) 84%, transparent);
  color: var(--on-candy);
  font-weight: 700;
  backdrop-filter: blur(8px) saturate(160%);
  box-shadow: 0 3px 16px var(--candy-glow),
              inset 0 1px 0 rgba(255, 255, 255, 0.42);
}
@supports (backdrop-filter: url(#glass-btn)) {
  .btn-primary { backdrop-filter: url(#glass-btn) blur(7px) saturate(160%); }
}
.btn-primary:hover {
  background: color-mix(in srgb, var(--candy-400) 88%, transparent);
  box-shadow: 0 5px 22px var(--candy-glow),
              inset 0 1px 0 rgba(255, 255, 255, 0.5);
}
.btn-primary:active { transform: scale(0.965); }

.btn-ghost {
  background: rgba(255,255,255,0.03);
  border-color: var(--line);
  color: var(--text-dim);
  min-height: 38px;
  padding: 7px 13px;
  font-size: 13px;
  backdrop-filter: blur(6px);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.08);
}
.btn-ghost:hover { background: rgba(255,255,255,0.07); color: var(--text); border-color: #38404f; }
.btn-ghost.danger:hover { color: var(--venue); border-color: rgba(255,107,107,0.4); }

.btn-sm { min-height: 36px; padding: 6px 12px; font-size: 12.5px; }
.btn-icon { min-height: 36px; width: 36px; padding: 0; font-size: 18px; line-height: 1; }

@keyframes pop {
  0%   { transform: scale(0.955); }
  45%  { transform: scale(1.035); }
  100% { transform: scale(1); }
}
.btn.did-succeed { animation: pop 420ms var(--spring); }

.btn.is-busy { color: transparent !important; pointer-events: none; }
.btn.is-busy::after {
  content: "";
  position: absolute; inset: 0; margin: auto;
  width: 17px; height: 17px;
  border: 2px solid rgba(255,255,255,0.28);
  border-top-color: currentColor;
  border-radius: 50%;
  color: var(--on-candy);
  animation: spin 620ms linear infinite;
}
.btn-ghost.is-busy::after { color: var(--text); }
@keyframes spin { to { transform: rotate(360deg); } }

/* ============================================================== dashboard */

.tiles {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 14px;
  margin-bottom: 18px;
}

.tile {
  padding: 16px 18px;
  background: var(--onyx-800);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.04);
}
.tile-label {
  font-size: 11.5px; font-weight: 650;
  letter-spacing: 0.6px; text-transform: uppercase;
  color: var(--text-faint);
}
/* Hero number: text tokens only, never a status colour, never animated. */
.tile-value {
  font-size: 32px; font-weight: 700;
  letter-spacing: -1px;
  color: var(--text);
  margin-top: 6px;
  font-variant-numeric: tabular-nums;
}
.tile-foot {
  display: flex; align-items: center; gap: 6px;
  font-size: 12px; color: var(--text-dim);
  margin-top: 4px;
}
.tile-dot { width: 7px; height: 7px; border-radius: 50%; flex: none; }
.tile-dot.ok { background: var(--ok); box-shadow: 0 0 0 3px var(--ok-wash); }
.tile-dot.warn { background: var(--player); box-shadow: 0 0 0 3px var(--player-wash); }
.tile-dot.idle { background: var(--text-faint); }

.dash-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
  gap: 18px;
  align-items: start;
}
@media (max-width: 980px) { .dash-grid { grid-template-columns: 1fr; } }

/* 7-day load strip — one hue, magnitude only, so no legend is needed. */
.load-strip {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 2px;
  align-items: end;
  height: 104px;
  padding: 18px 18px 0;
}
.load-col { display: flex; flex-direction: column; justify-content: flex-end; height: 100%; gap: 6px; }
.load-bar {
  width: 100%;
  min-height: 3px;
  border-radius: 4px 4px 0 0;   /* rounded data-end, anchored to the baseline */
  background: var(--candy-500);
  transition: height 420ms var(--ease);
}
.load-bar.is-empty { background: var(--onyx-500); }
.load-axis {
  display: grid; grid-template-columns: repeat(7, 1fr); gap: 2px;
  padding: 6px 18px 16px;
  border-bottom: 1px solid var(--line-soft);
}
.load-day {
  text-align: center;
  font-size: 10.5px; color: var(--text-faint);
  font-variant-numeric: tabular-nums;
}
.load-day b { display: block; color: var(--text-dim); font-weight: 600; }

/* ================================================================ schedule */

.cal-bar {
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px;
  padding: 11px 18px;
  border-bottom: 1px solid var(--line-soft);
}
.cal-nav { display: flex; gap: 6px; }
.cal-title { font-size: 14px; font-weight: 650; letter-spacing: -0.2px; }

.weekdays {
  display: grid; grid-template-columns: repeat(7, 1fr);
  background: var(--onyx-700);
  border-bottom: 1px solid var(--line-soft);
}
.weekdays div {
  text-align: center; padding: 7px 2px;
  font-size: 10.5px; font-weight: 700;
  letter-spacing: 0.7px; text-transform: uppercase;
  color: var(--text-faint);
}

.grid {
  display: grid; grid-template-columns: repeat(7, 1fr);
  gap: 1px; background: var(--line-soft);
}

.day {
  min-height: 108px;
  background: var(--onyx-800);
  padding: 6px;
  display: flex; flex-direction: column; gap: 3px;
}
.day.is-empty { background: var(--onyx-900); }
.day-num { font-family: var(--mono); font-size: 11px; color: var(--text-faint); padding: 1px 3px; }

/* Exactly one cell is today, and it is the only cell carrying the accent. */
.day.is-today { background: var(--onyx-700); }
.day.is-today .day-num {
  color: var(--on-candy);
  background: var(--candy-500);
  border-radius: 6px;
  font-weight: 700;
  align-self: flex-start;
  padding: 1px 6px;
}

.event {
  display: flex; flex-direction: column; gap: 1px;
  width: 100%; text-align: left;
  padding: 4px 6px;
  border: none;
  border-left: 2px solid var(--candy-600);
  border-radius: 5px;
  background: var(--onyx-600);
  color: var(--text);
  cursor: pointer;
  overflow: hidden;
  transition: transform 300ms var(--spring), background-color 140ms var(--ease),
              border-color 140ms var(--ease);
}
.event:hover { background: var(--onyx-500); border-left-color: var(--candy-400); }
.event:active { transform: scale(0.94); transition: transform 80ms ease-out; }
.event.is-selected {
  background: var(--candy-wash);
  border-left-color: var(--candy-400);
  box-shadow: inset 0 0 0 1px rgba(43,179,255,0.35);
}
.event-time { font-family: var(--mono); font-size: 10px; color: var(--candy-400); }
.event-name { font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.more { font-size: 10px; color: var(--text-faint); padding-left: 4px; }

.detail-card { padding: 16px 18px; }
.detail-teams { font-size: 16px; font-weight: 650; letter-spacing: -0.2px; }
.detail-when { font-size: 12.5px; color: var(--text-dim); margin-top: 3px; }
.detail-card dl { margin: 14px 0 0; }

/* =============================================================== matches ===
   Used by the dashboard's "next up" list. */

.match-row {
  display: grid;
  grid-template-columns: 62px minmax(0,1fr) auto;
  gap: 12px; align-items: center;
  padding: 11px 18px;
  border-bottom: 1px solid var(--line-soft);
}
.match-row:last-child { border-bottom: none; }
.match-when { font-family: var(--mono); font-size: 12px; color: var(--text); }
.match-when span { display: block; font-size: 10.5px; color: var(--text-faint); }
.match-teams { font-size: 13.5px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.match-meta { font-size: 11.5px; color: var(--text-faint); margin-top: 1px; }

.pill {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 2px 9px;
  border-radius: 999px;
  font-size: 11px; font-weight: 650;
  letter-spacing: 0.3px;
  border: 1px solid transparent;
}
.pill-sport { background: var(--onyx-500); color: var(--text-dim); border-color: var(--line); }
.pill-term  { background: var(--candy-wash); color: var(--candy-400); border-color: rgba(43,179,255,0.25); }
.pill-draft { background: var(--player-wash); color: var(--player); border-color: rgba(255,180,84,0.3); }
.pill-live  { background: var(--ok-wash); color: var(--ok); border-color: rgba(61,220,151,0.3); }

/* ============================================================== conflicts ===
   Each kind is a different colour because each demands a different fix. */

.conflicts {
  margin-top: 14px;
  border: 1px solid rgba(255,107,107,0.35);
  border-radius: var(--radius);
  background: rgba(255,107,107,0.05);
  overflow: hidden;
  animation: shake 380ms var(--ease), panel-in 240ms var(--ease);
}
@keyframes shake {
  0%,100% { transform: translateX(0); }
  22% { transform: translateX(-5px); }
  44% { transform: translateX(4px); }
  66% { transform: translateX(-2px); }
}
.conflicts-head {
  padding: 10px 13px;
  font-size: 12.5px; font-weight: 700;
  color: var(--venue);
  border-bottom: 1px solid rgba(255,107,107,0.2);
}
.conflict {
  display: flex; gap: 10px;
  padding: 10px 13px;
  border-bottom: 1px solid var(--line-soft);
  font-size: 12.5px;
}
.conflict:last-child { border-bottom: none; }
.conflict-bar { width: 3px; border-radius: 2px; flex: none; }
.c-venue .conflict-bar, .c-venue_external .conflict-bar { background: var(--venue); }
.c-player .conflict-bar, .c-player_external .conflict-bar { background: var(--player); }
.c-blackout .conflict-bar, .c-blackout_external .conflict-bar { background: var(--blackout); }
.c-invalid .conflict-bar { background: var(--text-faint); }

.conflict-kind { font-weight: 700; margin-bottom: 1px; }
.c-venue .conflict-kind, .c-venue_external .conflict-kind { color: var(--venue); }
.c-player .conflict-kind, .c-player_external .conflict-kind { color: var(--player); }
.c-blackout .conflict-kind, .c-blackout_external .conflict-kind { color: var(--blackout); }
.c-invalid .conflict-kind { color: var(--text-dim); }
.conflict-why { color: var(--text-dim); }
.conflict-why b { color: var(--text); font-weight: 600; }

.rest-meter {
  margin-top: 6px; height: 5px;
  border-radius: 3px; background: var(--onyx-500); overflow: hidden;
}
.rest-meter span {
  display: block; height: 100%;
  background: var(--blackout); border-radius: 3px;
  transition: width 700ms var(--spring);
}

/* ================================================================= drafts */

.draft {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--onyx-700);
  padding: 13px;
  animation: row-in 280ms var(--ease) both;
}
.draft + .draft { margin-top: 10px; }
.draft-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; }
.draft-id { font-family: var(--mono); font-size: 12px; color: var(--text-faint); }
.draft-teams { font-size: 13.5px; font-weight: 600; margin-top: 3px; }
.draft-when { font-size: 12px; color: var(--text-dim); margin-top: 2px; }
.draft-actions { display: flex; gap: 8px; margin-top: 12px; }
.draft-actions .btn { flex: 1; }
.draft.is-leaving { animation: row-out 280ms var(--ease) forwards; }

@keyframes row-in  { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }
@keyframes row-out { to { opacity: 0; transform: translateX(14px) scale(0.97); max-height: 0; margin: 0; padding-block: 0; } }
@keyframes panel-in { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: none; } }

/* =================================================================== rows */

.roster-row {
  display: flex; align-items: center; justify-content: space-between;
  gap: 10px;
  padding: 9px 11px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--onyx-700);
  animation: row-in 260ms var(--ease) both;
}
.roster-row.is-leaving { animation: row-out 240ms var(--ease) forwards; }
.roster-name { font-size: 13px; font-weight: 600; }
.roster-roll { font-family: var(--mono); font-size: 11.5px; color: var(--text-faint); }

.fixture {
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--onyx-700);
  display: flex; flex-direction: column; gap: 11px;
  animation: row-in 260ms var(--ease) both;
}

/* ================================================================ states */

.empty { padding: 40px 22px; text-align: center; color: var(--text-faint); }
.empty-mark {
  width: 42px; height: 42px; margin: 0 auto 12px;
  border-radius: 12px; border: 1px dashed var(--line);
  display: grid; place-items: center; font-size: 18px; color: var(--text-faint);
}
.empty-title { color: var(--text-dim); font-weight: 600; font-size: 13.5px; }
.empty-body { font-size: 12.5px; margin-top: 3px; }

.skeleton {
  height: 56px;
  border-bottom: 1px solid var(--line-soft);
  background: linear-gradient(90deg, var(--onyx-700) 25%, var(--onyx-600) 37%, var(--onyx-700) 63%);
  background-size: 400% 100%;
  animation: shimmer 1.3s ease-in-out infinite;
}
@keyframes shimmer { from { background-position: 100% 0; } to { background-position: 0 0; } }

.result {
  margin-top: 12px;
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  font-size: 12.5px;
  border: 1px solid transparent;
  animation: panel-in 220ms var(--ease);
}
.result.ok  { background: var(--ok-wash);  color: var(--ok);  border-color: rgba(61,220,151,0.28); }
.result.bad { background: var(--venue-wash); color: var(--venue); border-color: rgba(255,107,107,0.28); }
.result.info{ background: var(--onyx-600); color: var(--text-dim); border-color: var(--line); }

.stage {
  display: flex; align-items: center; gap: 10px;
  padding: 11px 13px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--onyx-700);
  margin-top: 12px;
  font-size: 12.5px;
}
.stage-dot { width: 9px; height: 9px; border-radius: 50%; background: var(--text-faint); flex: none;
  transition: background-color 260ms var(--ease), box-shadow 260ms var(--ease); }
.stage[data-state="RUNNING"] .stage-dot { background: var(--candy-500); animation: pulse 1.3s var(--ease) infinite; }
.stage[data-state="COMPLETED"] .stage-dot { background: var(--ok); box-shadow: 0 0 0 4px var(--ok-wash); }
.stage[data-state="FAILED"] .stage-dot { background: var(--venue); box-shadow: 0 0 0 4px var(--venue-wash); }
@keyframes pulse {
  0%   { box-shadow: 0 0 0 0 var(--candy-glow); }
  70%  { box-shadow: 0 0 0 9px rgba(43,179,255,0); }
  100% { box-shadow: 0 0 0 0 rgba(43,179,255,0); }
}

.stack { display: flex; flex-direction: column; gap: 10px; }
.between { display: flex; align-items: center; justify-content: space-between; gap: 10px; }

.kv { display: flex; justify-content: space-between; gap: 12px; font-size: 12.5px; padding: 6px 0; }
.kv + .kv { border-top: 1px solid var(--line-soft); }
.kv dt { color: var(--text-faint); }
.kv dd { margin: 0; color: var(--text); font-family: var(--mono); font-size: 12px; }

.accent-card {
  border-color: rgba(43,179,255,0.45);
  box-shadow: 0 0 0 1px rgba(43,179,255,0.12), 0 8px 30px rgba(43,179,255,0.10);
}
.accent-card .panel-head { border-bottom-color: rgba(43,179,255,0.2); }

.panel + .panel { margin-top: 18px; }

/* ================================================================= toasts
   Bottom-right, but never on top of the primary action. */

.toasts {
  position: fixed;
  right: 18px; bottom: 18px;
  z-index: 90;
  display: flex; flex-direction: column; gap: 9px;
  max-width: min(380px, calc(100vw - 36px));
  pointer-events: none;
}
.toast {
  display: flex; align-items: flex-start; gap: 10px;
  padding: 12px 14px;
  border-radius: var(--radius);
  background: rgba(28, 33, 42, 0.82);
  backdrop-filter: blur(14px) saturate(150%);
  border: 1px solid var(--line);
  box-shadow: 0 10px 34px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.14);
  font-size: 13px;
  pointer-events: auto;
  animation: toast-in 380ms var(--spring);
}
.toast.is-leaving { animation: toast-out 220ms var(--ease) forwards; }
@keyframes toast-in  { from { opacity: 0; transform: translateY(14px) scale(0.94); } to { opacity: 1; transform: none; } }
@keyframes toast-out { to { opacity: 0; transform: translateX(22px) scale(0.97); } }
.toast-bar { width: 3px; align-self: stretch; border-radius: 2px; background: var(--candy-500); flex: none; }
.toast.ok  .toast-bar { background: var(--ok); }
.toast.bad .toast-bar { background: var(--venue); }
.toast-title { font-weight: 650; }
.toast-body { color: var(--text-dim); font-size: 12.5px; margin-top: 1px; }

/* Motion is decoration and never carries information, so it all comes off. */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
  .btn:active { transform: none; }
  html { scroll-behavior: auto; }
}

