    cancel.type = "button";
    cancel.addEventListener("click", () => confirmCancelMatch(m, cancel, actions));
    actions.appendChild(why);
    actions.appendChild(cancel);
    card.appendChild(actions);
  } else if (state.session && m.status !== "CANCELLED") {
